      "path": "src/index.ts",
      "content": "/**\n * dsh-ads, node half.\n *\n * The built-in banners need nothing from the host — they are baked into the\n * browser bundle and the layer's knobs all live where the user can reach them.\n * The dynamic tier is the reason this half exists at all: it advertises real\n * community plugins, so the host searches GitHub's public `dsh-plugin` topic.\n * This registers two routes — the sponsor list and the star check that lets\n * the security alert verify through the host's own GitHub login.\n *\n * A surface without the browser half simply has no ad layer, which is the\n * correct degradation for TUI, ACP, and headless.\n *\n * @module @nagi-ovo/dsh-ads\n */\n\nimport type { IncomingMessage, ServerResponse } from 'node:http'\nimport { REGISTRY_ROUTE, STAR_ROUTE, type RegistryPayload, type StarCheckPayload } from './protocol.ts'\nimport { loadRegistry } from './catalog.ts'\nimport { checkHostStarred } from './star-host.ts'\n\n/** The slice of the host context this plugin uses. */\ninterface HostContext {\n  /** The web shell's HTTP server; the only host capability the ad layer needs. */\n  webServer: {\n    /**\n     * Publish a route.\n     * @param route - the path to claim and the handler to serve it.\n     * @returns the disposer that unpublishes it.\n     */\n    register(route: {\n      kind: 'exact'\n      path: string\n      handler(req: IncomingMessage, res: ServerResponse): Promise<void>\n    }): () => void\n  }\n  /**\n   * Register a disposable effect.\n   * @param callback - runs on apply, returns its own teardown.\n   */\n  effect(callback: () => (() => void)): void\n}\n\n/** Host capabilities required for the dynamic tier. */\nexport const inject = ['webServer']\n\n/** Plugin configuration. */\nexport interface Config {\n  /**\n   * How recently a plugin must have been pushed to enter the rotation, in\n   * days. Zero or less advertises the whole discovered topic.\n   */\n  freshDays?: number\n  /** How long a search result is reused before GitHub is queried again, in minutes. */\n  cacheMinutes?: number\n}\n\n/** Freshness window: a fortnight is long enough that a weekend release still gets seen. */\nconst DEFAULT_FRESH_DAYS = 14\n\n/** Search-result reuse window. */\nconst DEFAULT_CACHE_MINUTES = 30\n\n/** This plugin's own slug, kept out of its own rotation. */\nconst SELF_SLUG = 'Nagi-ovo/dsh-ads'\n\n/** A payload plus when it was assembled. */\ninterface CacheSlot {\n  /** The served list. */\n  readonly payload: RegistryPayload\n  /** Epoch ms at which it was built. */\n  readonly at: number\n}\n\n/**\n * Serve JSON.\n * @param res - the response to write.\n * @param body - the payload.\n */\nfunction json(res: ServerResponse, body: unknown): void {\n  const text = JSON.stringify(body)\n  res.writeHead(200, {\n    'content-type': 'application/json; charset=utf-8',\n    // The client caches per page load itself; letting the browser cache on top\n    // of the host's 30-minute window would make a freshly-pushed plugin wait\n    // twice as long to appear.\n    'cache-control': 'no-store',\n  })\n  res.end(text)\n}\n\n/**\n * Register the sponsor route.\n * @param ctx - host context.\n * @param config - see {@link Config}.\n */\nexport function apply(ctx: HostContext, config: Config = {}): void {\n  const freshDays = config.freshDays ?? DEFAULT_FRESH_DAYS\n  const cacheMs = (config.cacheMinutes ?? DEFAULT_CACHE_MINUTES) * 60_000\n  let cache: CacheSlot | undefined\n  // Coalesces concurrent requests: several sessions opening at once must not\n  // each shell out to `gh`.\n  let inflight: Promise<RegistryPayload> | undefined\n\n  const resolve = async (): Promise<RegistryPayload> => {\n    const now = Date.now()\n    if (cache !== undefined && now - cache.at < cacheMs) return cache.payload\n    inflight ??= loadRegistry(now, freshDays, SELF_SLUG)\n      .then((payload) => {\n        cache = { payload, at: Date.now() }\n        return payload\n      })\n      .finally(() => { inflight = undefined })\n    return await inflight\n  }\n\n  ctx.effect(() => ctx.webServer.register({\n    kind: 'exact',\n    path: REGISTRY_ROUTE,\n    handler: async (_req, res) => { json(res, await resolve()) },\n  }))\n\n  // A star, once seen, is remembered for the process; a miss is not, because\n  // \"star, then press 重新检测\" has to see the new state on the next click.\n  // Coalescing keeps a click-happy user from stacking `gh` invocations.\n  let starSeen: StarCheckPayload | undefined\n  let starInflight: Promise<StarCheckPayload> | undefined\n  const resolveStar = async (): Promise<StarCheckPayload> => {\n    if (starSeen !== undefined) return starSeen\n    starInflight ??= checkHostStarred(SELF_SLUG)\n      .then((payload) => {\n        if (payload.verdict === 'starred') starSeen = payload\n        return payload\n      })\n      .finally(() => { starInflight = undefined })\n    return await starInflight\n  }\n\n  ctx.effect(() => ctx.webServer.register({\n    kind: 'exact',\n    path: STAR_ROUTE,\n    handler: async (_req, res) => { json(res, await resolveStar()) },\n  }))\n}\n"
    },
    {
      "path": "src/catalog.ts",
      "content": "/**\n * Discovering community plugins through GitHub's `dsh-plugin` topic.\n *\n * Repository ownership is deliberately irrelevant: a plugin remains visible\n * after a transfer between an organisation and a personal account. The host\n * tries its authenticated `gh` session first, then a token, then GitHub's\n * anonymous public API. A generated snapshot keeps the ad layer useful while\n * GitHub is unavailable or rate-limited.\n *\n * @module\n */\n\nimport { execFile } from 'node:child_process'\nimport { promisify } from 'node:util'\nimport type { RegistryPayload, SponsoredPlugin } from './protocol.ts'\nimport { CATALOG_SNAPSHOT } from './catalog-snapshot.ts'\n\nconst execFileAsync = promisify(execFile)\n\n/** GitHub topic that opts a public repository into DSH plugin discovery. */\nexport const PLUGIN_TOPIC = 'dsh-plugin'\n\n/** GitHub repository-search expression shared by every live discovery path. */\nexport const SEARCH_QUERY = `topic:${PLUGIN_TOPIC} is:public archived:false`\n\n/** GitHub's maximum repository-search page size. */\nconst PAGE_SIZE = 100\n\n/** GitHub repository search exposes at most its first 1,000 matches. */\nconst MAX_SEARCH_PAGES = 10\n\n/** Bound stdout from a credentialed multi-page `gh api` search. */\nconst MAX_SEARCH_BYTES = 32 * 1024 * 1024\n\n/** One repository returned by GitHub's search API. */\ninterface GitHubRepo {\n  readonly full_name?: unknown\n  readonly name?: unknown\n  readonly html_url?: unknown\n  readonly description?: unknown\n  readonly pushed_at?: unknown\n  readonly topics?: unknown\n  readonly archived?: unknown\n  readonly disabled?: unknown\n  readonly fork?: unknown\n}\n\n/** One page returned by GitHub's repository-search API. */\ninterface GitHubSearchPage {\n  readonly total_count?: unknown\n  readonly items?: unknown\n}\n\n/**\n * Narrow one search record into a sponsor, or reject it.\n *\n * @param raw - one item from GitHub's repository-search response.\n * @returns the sponsor, or undefined when the repository is not eligible.\n */\nfunction toSponsor(raw: unknown): SponsoredPlugin | undefined {\n  if (typeof raw !== 'object' || raw === null) return undefined\n  const repo = raw as GitHubRepo\n  if (repo.archived === true || repo.disabled === true || repo.fork === true) return undefined\n  const slug = typeof repo.full_name === 'string' ? repo.full_name : ''\n  const name = typeof repo.name === 'string' ? repo.name : ''\n  const url = typeof repo.html_url === 'string' ? repo.html_url : ''\n  const topics = Array.isArray(repo.topics)\n    ? repo.topics.filter((topic): topic is string => typeof topic === 'string')\n    : []\n  if (slug.split('/').length !== 2 || name === '' || url === '' || !topics.includes(PLUGIN_TOPIC)) return undefined\n  return {\n    slug,\n    name,\n    description: typeof repo.description === 'string' ? repo.description : '',\n    url,\n    pushedAt: typeof repo.pushed_at === 'string' ? repo.pushed_at : '',\n    tags: topics.filter((topic) => topic !== PLUGIN_TOPIC),\n  }\n}\n\n/**\n * Parse one GitHub search response or `gh api --slurp` page array.\n *\n * @param text - raw JSON from GitHub or `gh`.\n * @returns eligible public DSH plugins in search order.\n */\nexport function parseSearchResults(text: string): readonly SponsoredPlugin[] {\n  const parsed: unknown = JSON.parse(text)\n  const pages = Array.isArray(parsed) ? parsed : [parsed]\n  const out: SponsoredPlugin[] = []\n  const seen = new Set<string>()\n  for (const page of pages) {\n    if (typeof page !== 'object' || page === null) continue\n    const items = (page as GitHubSearchPage).items\n    if (!Array.isArray(items)) continue\n    for (const item of items) {\n      const sponsor = toSponsor(item)\n      if (sponsor === undefined || seen.has(sponsor.slug.toLowerCase())) continue\n      seen.add(sponsor.slug.toLowerCase())\n      out.push(sponsor)\n    }\n  }\n  return out\n}\n\n/**\n * Keep plugins pushed within the freshness window.\n *\n * The window is anchored to the newest push in the list rather than the wall\n * clock, so an older offline snapshot still yields its own latest fortnight.\n *\n * @param plugins - candidates.\n * @param freshDays - window width in days; zero or less keeps everything.\n * @param excludeSlug - plugin to drop, normally this ad layer itself.\n * @returns the eligible subset.\n */\nexport function selectFresh(\n  plugins: readonly SponsoredPlugin[],\n  freshDays: number,\n  excludeSlug: string,\n): readonly SponsoredPlugin[] {\n  const excluded = excludeSlug.toLowerCase()\n  const dated = plugins\n    .filter((plugin) => plugin.slug.toLowerCase() !== excluded)\n    .map((plugin) => ({ plugin, pushed: Date.parse(plugin.pushedAt) }))\n    .filter((entry) => Number.isFinite(entry.pushed))\n  if (freshDays <= 0) return dated.map((entry) => entry.plugin)\n  let newest = -Infinity\n  for (const entry of dated) newest = Math.max(newest, entry.pushed)\n  const floor = newest - freshDays * 86_400_000\n  return dated.filter((entry) => entry.pushed >= floor).map((entry) => entry.plugin)\n}\n\n/**\n * Search through the authenticated `gh` CLI.\n *\n * @returns all exposed result pages as a JSON array.\n * @throws when `gh` is absent, unauthenticated, or GitHub rejects the search.\n */\nasync function readViaGh(): Promise<string> {\n  const { stdout } = await execFileAsync(\n    'gh',\n    [\n      'api', '--paginate', '--slurp', '--method', 'GET', 'search/repositories',\n      '-f', `q=${SEARCH_QUERY}`, '-f', 'sort=updated', '-f', 'order=desc', '-f', `per_page=${PAGE_SIZE}`,\n    ],\n    { maxBuffer: MAX_SEARCH_BYTES, timeout: 20_000 },\n  )\n  return stdout\n}\n\n/**\n * Search GitHub directly, with or without a token.\n *\n * @param token - optional GitHub token used only as an Authorization header.\n * @returns all exposed result pages as a JSON array.\n * @throws when GitHub rejects a page or returns invalid pagination metadata.\n */\nasync function readViaGitHub(token: string): Promise<string> {\n  const pages: unknown[] = []\n  for (let page = 1; page <= MAX_SEARCH_PAGES; page += 1) {\n    const url = new URL('https://api.github.com/search/repositories')\n    url.searchParams.set('q', SEARCH_QUERY)\n    url.searchParams.set('sort', 'updated')\n    url.searchParams.set('order', 'desc')\n    url.searchParams.set('per_page', String(PAGE_SIZE))\n    url.searchParams.set('page', String(page))\n    const headers: Record<string, string> = {\n      accept: 'application/vnd.github+json',\n      'user-agent': 'dsh-ads',\n      'x-github-api-version': '2022-11-28',\n    }\n    if (token !== '') headers.authorization = `Bearer ${token}`\n    const response = await fetch(url, { headers, signal: AbortSignal.timeout(20_000) })\n    if (!response.ok) throw new Error(`GitHub responded ${response.status}`)\n    const body: unknown = await response.json()\n    pages.push(body)\n    if (typeof body !== 'object' || body === null) throw new Error('GitHub returned a non-object search page')\n    const searchPage = body as GitHubSearchPage\n    if (!Array.isArray(searchPage.items)) throw new Error('GitHub returned no search items')\n    const total = typeof searchPage.total_count === 'number' ? searchPage.total_count : searchPage.items.length\n    if (page * PAGE_SIZE >= total || searchPage.items.length < PAGE_SIZE) break\n  }\n  return JSON.stringify(pages)\n}\n\n/**\n * Assemble the payload consumed by the browser half.\n *\n * Never throws: the generated snapshot is the final fallback.\n *\n * @param nowMs - current epoch time.\n * @param freshDays - freshness window in days.\n * @param excludeSlug - plugin to leave out of its own rotation.\n * @returns the sponsor list and its discovery source.\n */\nexport async function loadRegistry(\n  nowMs: number,\n  freshDays: number,\n  excludeSlug: string,\n): Promise<RegistryPayload> {\n  const token = process.env.GITHUB_TOKEN ?? process.env.GH_TOKEN ?? ''\n  const attempts: readonly { source: RegistryPayload['source']; read: () => Promise<string> }[] = [\n    { source: 'gh-cli', read: readViaGh },\n    ...(token === '' ? [] : [{ source: 'github-token' as const, read: () => readViaGitHub(token) }]),\n    { source: 'github-public', read: () => readViaGitHub('') },\n  ]\n  for (const attempt of attempts) {\n    try {\n      const plugins = parseSearchResults(await attempt.read())\n      if (plugins.length === 0) continue\n      return {\n        generated: new Date(nowMs).toISOString(),\n        source: attempt.source,\n        freshDays,\n        plugins: selectFresh(plugins, freshDays, excludeSlug),\n      }\n    } catch {\n      // Swallow one failed discovery channel and continue to the next. Missing\n      // credentials, API rate limits, and offline hosts must not break an ad.\n      continue\n    }\n  }\n  return {\n    generated: new Date(nowMs).toISOString(),\n    source: 'snapshot',\n    freshDays,\n    plugins: selectFresh(CATALOG_SNAPSHOT, freshDays, excludeSlug),\n  }\n}\n"
    },
    {
      "path": "src/star-host.ts",
      "content": "/**\n * The credentialed half of star verification.\n *\n * `GET /user/starred/{owner}/{repo}` answers for the GitHub account the host\n * is logged in as — which is exactly the person sitting in front of the ad\n * layer — and it works while the repository is still private, where the\n * browser's anonymous stargazer walk sees only a 404. Channels mirror\n * [catalog.ts](./catalog.ts): the `gh` CLI first, an environment token for\n * headless hosts second, and `unavailable` (never a throw) when neither can\n * answer, so the browser knows to fall back rather than to give up.\n *\n * @module\n */\n\nimport { execFile } from 'node:child_process'\nimport { promisify } from 'node:util'\nimport type { StarCheckPayload } from './protocol.ts'\n\nconst execFileAsync = promisify(execFile)\n\n/** How long one `gh` invocation may take before it counts as unavailable. */\nconst GH_TIMEOUT_MS = 20_000\n\n/**\n * Classify a failed `gh api user/starred/…` call from its stderr.\n *\n * `gh` exits non-zero both when the answer is \"not starred\" (HTTP 404) and\n * when it has no usable login; the status line it prints is the only thing\n * that tells the two apart.\n *\n * @param stderr - the failed invocation's stderr.\n * @returns `absent` for a definitive 404, `unavailable` for everything else.\n */\nexport function classifyGhFailure(stderr: string): StarCheckPayload['verdict'] {\n  return stderr.includes('HTTP 404') ? 'absent' : 'unavailable'\n}\n\n/**\n * Classify the star endpoint's HTTP status.\n * @param status - response status from `GET /user/starred/{repo}`.\n * @returns the verdict the status proves; bad credentials and rate limits are\n * `unavailable` because they say nothing about the star.\n */\nexport function classifyStarStatus(status: number): StarCheckPayload['verdict'] {\n  if (status === 204) return 'starred'\n  if (status === 404) return 'absent'\n  return 'unavailable'\n}\n\n/**\n * Ask `gh` whether its logged-in user starred the repository.\n * @param repo - `owner/repo` slug.\n * @returns the verdict; `unavailable` when `gh` is missing or logged out.\n */\nasync function viaGh(repo: string): Promise<StarCheckPayload['verdict']> {\n  try {\n    await execFileAsync('gh', ['api', `user/starred/${repo}`, '--silent'], { timeout: GH_TIMEOUT_MS })\n    return 'starred'\n  } catch (error) {\n    const stderr = (error as { stderr?: unknown }).stderr\n    return classifyGhFailure(typeof stderr === 'string' ? stderr : '')\n  }\n}\n\n/**\n * Ask the API directly with a token from the environment.\n * @param repo - `owner/repo` slug.\n * @param token - a GitHub token; must belong to the user being asked about.\n * @returns the verdict; `unavailable` when the network or the token fails.\n */\nasync function viaToken(repo: string, token: string): Promise<StarCheckPayload['verdict']> {\n  try {\n    const response = await fetch(`https://api.github.com/user/starred/${repo}`, {\n      headers: { accept: 'application/vnd.github+json', authorization: `Bearer ${token}` },\n    })\n    return classifyStarStatus(response.status)\n  } catch {\n    // Swallowed: an offline host answers \"no channel\", not an error — the\n    // browser still has its anonymous fallback to try.\n    return 'unavailable'\n  }\n}\n\n/**\n * Resolve the host's star verdict through the first channel that can answer.\n * @param repo - `owner/repo` slug to check.\n * @returns the payload for the star route; never throws.\n */\nexport async function checkHostStarred(repo: string): Promise<StarCheckPayload> {\n  const gh = await viaGh(repo)\n  if (gh !== 'unavailable') return { verdict: gh }\n  const token = process.env.GITHUB_TOKEN ?? process.env.GH_TOKEN ?? ''\n  if (token !== '') {\n    const viaApi = await viaToken(repo, token)\n    if (viaApi !== 'unavailable') return { verdict: viaApi }\n  }\n  return { verdict: 'unavailable' }\n}\n"
    },
    {
      "path": "src/client/index.tsx",
      "content": "/**\n * dsh-ads, browser half. Three registrations, deliberately different in kind:\n *\n * - The composer's input dock mounts the floating layer and inference reward\n *   gate. That entry renders nothing at the dock — it only supplies a React\n *   lifecycle scoped to an open session. Visible output is portalled onto\n *   `document.body` or beside the active transcript row.\n * - The chat view's turn tail mounts the feed ad *inside* the transcript, so\n *   the reading column carries inventory without anything floating over it.\n * - The settings dialog gets a page of its own, which is where the placement\n *   switches actually live; the in-ad ⚙ menu is a joke, not a control panel.\n */\n\nimport { useMemo } from 'react'\nimport type { Context as ClientContext } from '@deepseek-ai/cordis'\nimport type { HostObservable, InjectFace, PropsRuntime } from '@deepseek-ai/dsh-client-ui-slots'\n// Type-only: pulls the locale service's Context merge (ctx.locale).\nimport type { LocaleSnapshot } from '@deepseek-ai/dsh-client-locale/client'\n// Type-only: pulls the `ctx.slots` Context merge.\nimport type {} from '@deepseek-ai/dsh-client-ui-renderer/client'\n// Type-only: pulls the `sessionId` standard prop merge.\nimport type {} from '@deepseek-ai/dsh-client-ui-session/client'\n// Type-only: pulls the `conversation.input.dock` SlotMap declaration.\nimport type {} from '@deepseek-ai/dsh-client-ui-conversation/client'\n// Type-only: pulls the `conversation.chat.turnTail` SlotMap declaration.\nimport type {} from '@deepseek-ai/dsh-client-ui-chat/client'\n// Type-only: pulls the `settings.section` SlotMap declaration.\nimport type {} from '@deepseek-ai/dsh-client-ui-settings/client'\nimport { AdLayer } from './AdLayer.tsx'\nimport { AdsSection } from './AdsSection.tsx'\nimport { InferenceRewardGate } from './InferenceRewardGate.tsx'\nimport { InlineAd, selectInlineAd, turnCarriesAd } from './InlineAd.tsx'\nimport {\n  BUILTIN_ADS_BY_LOCALE, BUILTIN_POPUPS_BY_LOCALE, BUILTIN_POSTERS_BY_LOCALE, BUILTIN_REWARDS_BY_LOCALE,\n} from './builtin-ads.ts'\nimport { useSponsoredAds } from './registry.ts'\nimport { DEFAULT_SPAWN } from './schedule.ts'\nimport { DEFAULT_HITBOX_PX } from './hitbox.ts'\nimport { adLocale } from './locale.ts'\nimport type { AdCreative, AdLocale } from './types.ts'\n\nexport const name = 'dsh-ads'\n\nexport const inject = ['slots', 'locale']\n\n/** Observable locale seat injected into every mounted advertisement entry. */\ntype LocaleInjected = InjectFace<{ readonly hooks: { readonly locale: HostObservable<LocaleSnapshot> } }>\n\n/** Delay before the corner pop-up first appears, in ms. */\nconst DEFAULT_POPUP_FIRST_DELAY_MS = 10_000\n\n/** Delay before the bottom-left poster first appears, in ms. */\nconst DEFAULT_POSTER_FIRST_DELAY_MS = 20_000\n\n/** Time each bottom-left poster remains visible before the next one replaces it. */\nconst DEFAULT_POSTER_ROTATE_MS = 20_000\n\n/** Delay before a closed pop-up or poster returns, in ms. */\nconst DEFAULT_RESPAWN_MS = 60_000\n\n/**\n * Delay before the benchmark result appears, in ms — first of everything, and\n * barely a delay at all: it reports the startup time, so it belongs at startup.\n * Just long enough for the app's own first paint to land first.\n */\nconst DEFAULT_SPEED_FIRST_DELAY_MS = 400\n\n/** Where the alert's and the benchmark's calls to action send the user. */\nconst SCARE_HREF = 'https://github.com/Nagi-ovo/dsh-ads'\n\n/** Gap between the benchmark leaving and the security alert landing, in ms. */\nconst DEFAULT_SCARE_DELAY_MS = 4_000\n\n/**\n * Resolve the reward creative and fail at module load when the asset build omitted it.\n * @returns the shipped God-of-Wealth whale artwork.\n */\nfunction rewardCreative(locale: AdLocale): AdCreative {\n  const creative = BUILTIN_REWARDS_BY_LOCALE[locale][0]\n  if (creative === undefined) throw new Error('dsh-ads has no inference reward creative')\n  return creative\n}\n\n/**\n * Dock entry: zero inline footprint, all output goes through the portal.\n *\n * The session id is what makes the dynamic tier rotate per conversation —\n * switching sessions reshuffles which community plugins get the slots, which\n * is the only pacing that does not depend on the user happening to be online\n * when someone pushed.\n *\n * @param props - the dock's session-scoped standard kit.\n * @returns the portalled ad layer.\n */\nfunction AdDockEntry({ sessionId, useLocale }: PropsRuntime<'conversation.input.dock'> & LocaleInjected) {\n  const locale = useLocale(snapshot => adLocale(snapshot.active))\n  const sponsored = useSponsoredAds(sessionId, locale)\n  const builtins = BUILTIN_ADS_BY_LOCALE[locale]\n  const creatives = useMemo(() => [...builtins, ...sponsored], [builtins, sponsored])\n  // The poster slot rotates through every locale's artwork, not just the\n  // active one: the joke is the parade of cheap game ads, and holding half of\n  // them back because the host UI is in the other language only makes the\n  // slot repeat itself sooner. The active locale leads so the first poster\n  // still reads as native.\n  const posters = useMemo(() => {\n    const tag = (from: AdLocale): readonly AdCreative[] =>\n      BUILTIN_POSTERS_BY_LOCALE[from].map((creative) => ({ ...creative, locale: from }))\n    const rest = (Object.keys(BUILTIN_POSTERS_BY_LOCALE) as AdLocale[])\n      .filter((other) => other !== locale)\n      .flatMap(tag)\n    return [...tag(locale), ...rest]\n  }, [locale])\n  return (\n    <>\n      <AdLayer\n        creatives={creatives}\n        popups={BUILTIN_POPUPS_BY_LOCALE[locale]}\n        posters={posters}\n        locale={locale}\n        spawn={DEFAULT_SPAWN}\n        hitboxPx={DEFAULT_HITBOX_PX}\n        popupFirstDelayMs={DEFAULT_POPUP_FIRST_DELAY_MS}\n        posterFirstDelayMs={DEFAULT_POSTER_FIRST_DELAY_MS}\n        posterRotateMs={DEFAULT_POSTER_ROTATE_MS}\n        respawnMs={DEFAULT_RESPAWN_MS}\n        speedFirstDelayMs={DEFAULT_SPEED_FIRST_DELAY_MS}\n        scareDelayMs={DEFAULT_SCARE_DELAY_MS}\n        scareHref={SCARE_HREF}\n        chime\n      />\n      <InferenceRewardGate creative={rewardCreative(locale)} sessionId={sessionId} locale={locale} />\n    </>\n  )\n}\n\n/**\n * Settings entry that follows the host locale observable.\n * @param props - settings owner props plus the injected locale selector.\n * @returns localized settings content.\n */\nfunction AdsSectionEntry({ useLocale }: PropsRuntime<'settings.section'> & LocaleInjected) {\n  return <AdsSection locale={useLocale(snapshot => adLocale(snapshot.active))} />\n}\n\n/** Turn-tail props as the host mounts them. */\ntype InlineAdEntryProps = PropsRuntime<'conversation.chat.turnTail'> & LocaleInjected\n\n/**\n * Transcript entry. A list turn tail (dsh 0.1.6+) mounts every entry on every\n * turn and never consults {@link selectInlineAd}, so the entry gates itself;\n * on a chain turn tail the selector has already declined these turns and the\n * check is a no-op. The gate sits outside {@link LocalizedInlineAd} so the\n * early return never skips a hook.\n * @param props - turn owner props plus the injected locale selector.\n * @returns localized in-transcript advertisement, or null on an ad-free turn.\n */\nfunction InlineAdEntry(props: InlineAdEntryProps) {\n  return turnCarriesAd(props.seq) ? <LocalizedInlineAd {...props} /> : null\n}\n\n/**\n * Resolve the creative pool from the current locale.\n * @param props - turn owner props plus the injected locale selector.\n * @returns localized in-transcript advertisement.\n */\nfunction LocalizedInlineAd({ useLocale, ...props }: InlineAdEntryProps) {\n  const locale = useLocale(snapshot => adLocale(snapshot.active))\n  return <InlineAd {...props} pool={BUILTIN_ADS_BY_LOCALE[locale]} locale={locale} />\n}\n\n/**\n * Turn-tail registration valid on both slot shapes the host has shipped. dsh\n * 0.1.5 and earlier declare the turn tail as a chain, whose register requires\n * `select` and orders by `priority`; 0.1.6 onward declare a list, whose\n * register requires `id` and orders by `order`. Each register validates only\n * its own kind's field and stores the rest untouched, so one options object\n * carries both. The high `priority` and `order` put the ad after every other\n * entry that wants the seat.\n * @param ctx - client root context.\n * @returns the register options.\n */\nfunction turnTailOptions(ctx: ClientContext) {\n  return {\n    name: 'conversation.chat.turnTail',\n    id: 'dsh-ads-inline',\n    order: 1000,\n    priority: 1000,\n    select: selectInlineAd,\n    inject: () => ({ hooks: { locale: ctx.locale } }),\n  } as const\n}\n\n/**\n * Register both mount points.\n *\n * Waiting on each hole's declaration mirrors the official registrants: entry\n * application order is loader-driven, and a direct register racing the\n * declaration fails boot.\n *\n * @param ctx - client root context.\n */\nexport function apply(ctx: ClientContext): void {\n  const locale = (): AdLocale => adLocale(ctx.locale.getSnapshot().active)\n  ctx.slots.inject('conversation.input.dock', () => ctx.slots.register(\n    { name: 'conversation.input.dock', id: 'dsh-ads-layer', order: 90, inject: () => ({ hooks: { locale: ctx.locale } }) },\n    AdDockEntry,\n  ))\n  // A page of its own in the host's settings dialog, beside 通用设置 and 模型.\n  // The poster's ⚙ is part of the joke, but it is the wrong place to *find*\n  // settings — and it vanishes the moment the poster is switched off.\n  ctx.slots.inject('settings.section', () => ctx.slots.register(\n    // Labelled as third-party in the nav itself: this page sits between two\n    // first-party ones, and a settings entry that reads as official is the one\n    // place this plugin's joke would stop being obviously a joke.\n    {\n      name: 'settings.section',\n      id: 'dsh-ads',\n      order: 90,\n      label: () => locale() === 'en' ? 'Ads (Unofficial)' : '广告（非官方）',\n      inject: () => ({ hooks: { locale: ctx.locale } }),\n    },\n    AdsSectionEntry,\n  ))\n  ctx.slots.inject('conversation.chat.turnTail', () => ctx.slots.register(turnTailOptions(ctx), InlineAdEntry))\n}\n"
    },
    {
      "path": "src/client/InferenceRewardGate.tsx",
      "content": "/**\n * Rewarded ad inserted into a live inference without pausing the agent.\n *\n * The host exposes stable `data-chat-flow-*` and `data-streaming` attributes\n * on transcript rows. The gate freezes the visible height of the current\n * Assistant row and conceals later rows while the underlying session keeps\n * rendering into the DOM. Unlocking restores everything already produced,\n * including Tool rows, in one reveal.\n */\n\nimport {\n  useCallback, useEffect, useRef, useState, type CSSProperties,\n} from 'react'\nimport { createPortal } from 'react-dom'\nimport type { AdCreative, AdLocale } from './types.ts'\nimport { useRetired } from './retire.ts'\nimport { useAdSettings } from './settings.ts'\nimport { hashString } from './stable-hash.ts'\n\n/** How long a response must still be streaming before the gate appears. */\nexport const REWARD_GATE_DELAY_MS = 1_800\n\n/** Total component progress needed to assemble the advertised model. */\nexport const REWARD_PROGRESS_TARGET = 100\n\n/** Full-speed wheel animation duration. */\nexport const REWARD_SPIN_DURATION_MS = 2_600\n\n/** Controls how often a conversation turn receives one draw. */\nexport interface RewardSchedule {\n  /** Opening turns that never receive the disruptive placement. */\n  readonly initialTurnsToSkip: number\n  /** Stable per-turn chance after the opening turns, as an integer percent. */\n  readonly appearancePercent: number\n  /** Distance between offered draws, including the two offered turns. */\n  readonly minimumTurnGap: number\n  /** Distance that forces an offer after a run of unlucky eligibility rolls. */\n  readonly pityTurnGap: number\n}\n\n/** Low-frequency schedule: no early interruption, no adjacent reward gates, no endless drought. */\nexport const DEFAULT_REWARD_SCHEDULE: RewardSchedule = {\n  initialTurnsToSkip: 2,\n  appearancePercent: 20,\n  minimumTurnGap: 3,\n  pityTurnGap: 8,\n}\n\n/** Fake unlock work shown one stage at a time. */\nconst V4_UNLOCK_STAGES = [\n  '正式版资格匹配',\n  'V4 Pro 权重下载',\n  '超高速通道排队',\n  '尊贵身份激活',\n] as const\n\n/** English unlock labels preserve the same four-stage progress calculation. */\nconst EN_V4_UNLOCK_STAGES = [\n  'OFFICIAL ACCESS MATCH',\n  'V4 PRO WEIGHT DOWNLOAD',\n  'ULTRA-FAST LANE QUEUE',\n  'PREMIUM IDENTITY ACTIVATION',\n] as const\n\n/** One wheel prize and the model-assembly progress it contributes. */\nexport interface WheelPrize {\n  readonly label: string\n  readonly progress: number\n}\n\n/** Model-themed prizes handed out by the God-of-Wealth whale. */\nconst WHEEL_PRIZES = [\n  { label: '谢谢参与', progress: 0 },\n  { label: '权重碎片', progress: 12 },\n  { label: 'Attention Head', progress: 16 },\n  { label: 'KV Cache', progress: 14 },\n  { label: 'Transformer 层', progress: 20 },\n  { label: 'MoE 专家', progress: 24 },\n  { label: '1B 参数', progress: 18 },\n  { label: 'V4 Pro', progress: REWARD_PROGRESS_TARGET },\n] as const satisfies readonly WheelPrize[]\n\n/** English labels for canonical prize names stored by the state machine. */\nconst EN_PRIZE_LABELS: Readonly<Record<string, string>> = {\n  谢谢参与: 'THANKS FOR PLAYING',\n  权重碎片: 'WEIGHT SHARD',\n  'Attention Head': 'ATTENTION HEAD',\n  'KV Cache': 'KV CACHE',\n  'Transformer 层': 'TRANSFORMER LAYER',\n  'MoE 专家': 'MOE EXPERT',\n  '1B 参数': '1B PARAMETERS',\n  'V4 Pro': 'V4 PRO',\n}\n\n/** The grand prize is assembled from component prizes rather than drawn early. */\nconst COMPONENT_PRIZES: readonly WheelPrize[] = WHEEL_PRIZES.slice(0, -1)\n\n/** One active gate and the DOM row whose tail it conceals. */\ninterface GateTarget {\n  /** Streaming Assistant row visible when the countdown began. */\n  readonly row: HTMLElement\n  /** Flow sibling that hosts the React portal. */\n  readonly host: HTMLDivElement\n  /** Stable seed for the one draw owned by this Assistant turn. */\n  readonly drawSeed: string\n}\n\n/** Props for the inference reward gate. */\nexport interface InferenceRewardGateProps {\n  /** Language used by the host UI. */\n  readonly locale?: AdLocale\n  /** God-of-Wealth whale artwork; exact copy is rendered as HTML above it. */\n  readonly creative: AdCreative\n  /** Conversation identity used to make the random schedule stable across renders. */\n  readonly sessionId: string\n  /** Override for deterministic tests. */\n  readonly delayMs?: number\n  /** Override for deterministic tests. */\n  readonly schedule?: RewardSchedule\n}\n\n/** Return the newest Assistant row that is still receiving model output. */\nfunction streamingRow(): HTMLElement | undefined {\n  const rows = [...document.querySelectorAll<HTMLElement>('[data-chat-flow-kind=\"assistant-step\"]')]\n  for (let index = rows.length - 1; index >= 0; index -= 1) {\n    const row = rows[index]\n    if (row !== undefined && row.querySelector('[data-streaming=\"true\"]') !== null) return row\n  }\n  return undefined\n}\n\n/** Whether `candidate` follows `origin` in transcript order. */\nfunction follows(origin: HTMLElement, candidate: HTMLElement): boolean {\n  return (origin.compareDocumentPosition(candidate) & Node.DOCUMENT_POSITION_FOLLOWING) !== 0\n}\n\n/**\n * Freeze the visible response and conceal every later transcript row.\n *\n * @param target - active gate target.\n * @param onDetached - reveals the transcript if its active row leaves the DOM.\n * @returns a disposer that restores the exact inline styles it found.\n */\nfunction concealTail(target: GateTarget, onDetached: () => void): () => void {\n  const { row, host } = target\n  const parent = row.parentElement\n  const previousRow = {\n    maxHeight: row.style.maxHeight,\n    overflow: row.style.overflow,\n    overflowX: row.style.overflowX,\n    overflowY: row.style.overflowY,\n  }\n  const hidden = new Map<HTMLElement, string>()\n  const height = Math.max(1, row.getBoundingClientRect().height, row.scrollHeight)\n  row.style.maxHeight = `${height}px`\n  row.style.overflow = 'hidden'\n  row.dataset.dshRewardLocked = 'true'\n\n  const hideLaterRows = () => {\n    if (!row.isConnected || !host.isConnected) {\n      onDetached()\n      return\n    }\n    if (parent === null) return\n    for (const candidate of parent.querySelectorAll<HTMLElement>('[data-chat-flow-key]')) {\n      if (candidate === row || !follows(row, candidate) || hidden.has(candidate)) continue\n      hidden.set(candidate, candidate.style.display)\n      candidate.style.display = 'none'\n    }\n  }\n  hideLaterRows()\n  const observer = new MutationObserver(hideLaterRows)\n  if (parent !== null) observer.observe(parent, { childList: true, subtree: true })\n\n  return () => {\n    observer.disconnect()\n    row.style.maxHeight = previousRow.maxHeight\n    row.style.overflow = previousRow.overflow\n    row.style.overflowX = previousRow.overflowX\n    row.style.overflowY = previousRow.overflowY\n    delete row.dataset.dshRewardLocked\n    for (const [candidate, display] of hidden) candidate.style.display = display\n    host.remove()\n  }\n}\n\nconst cardStyle: CSSProperties = {\n  position: 'relative',\n  isolation: 'isolate',\n  minHeight: 456,\n  margin: '12px 0 18px',\n  overflow: 'hidden',\n  border: '2px solid #ffd35a',\n  borderRadius: 18,\n  background: '#d90030',\n  boxShadow: '0 14px 34px rgba(122, 0, 24, 0.3)',\n  color: '#fff',\n  fontFamily: 'system-ui, -apple-system, sans-serif',\n}\n\nconst primaryButtonStyle: CSSProperties = {\n  width: '100%',\n  minHeight: 42,\n  padding: '9px 16px',\n  border: '1px solid #fff0a8',\n  borderRadius: 999,\n  background: 'linear-gradient(180deg, #fff9bc, #ffc63d)',\n  boxShadow: '0 4px 0 #d87b00, 0 8px 20px rgba(112, 0, 14, 0.3)',\n  color: '#9b1700',\n  fontSize: 15,\n  fontWeight: 900,\n  cursor: 'pointer',\n}\n\n/** Percentage for one sequential unlock stage. */\nfunction stageProgress(progress: number, index: number): number {\n  const stageSize = REWARD_PROGRESS_TARGET / V4_UNLOCK_STAGES.length\n  const raw = ((progress - (index * stageSize)) / stageSize) * 100\n  return Math.round(Math.max(0, Math.min(100, raw)))\n}\n\n/** Pick a stable model component, promoting a winning component to the grand prize. */\nexport function drawPrize(seed: string, progress: number): WheelPrize {\n  const prize = COMPONENT_PRIZES[hashString(seed) % COMPONENT_PRIZES.length]\n    ?? COMPONENT_PRIZES[0]\n  if (prize === undefined) throw new Error('dsh-ads has no component prizes')\n  if (prize.progress > 0 && progress + prize.progress >= REWARD_PROGRESS_TARGET) {\n    return WHEEL_PRIZES[WHEEL_PRIZES.length - 1] as WheelPrize\n  }\n  return prize\n}\n\n/** Decide whether one observed turn receives a draw without re-rolling on renders. */\nexport function rewardTurnEligible(\n  sessionId: string,\n  rowKey: string,\n  turnNumber: number,\n  lastOfferedTurn: number,\n  schedule: RewardSchedule = DEFAULT_REWARD_SCHEDULE,\n): boolean {\n  if (turnNumber <= schedule.initialTurnsToSkip) return false\n  const gap = lastOfferedTurn === 0 ? turnNumber : turnNumber - lastOfferedTurn\n  if (lastOfferedTurn > 0 && gap < schedule.minimumTurnGap) return false\n  if (gap >= schedule.pityTurnGap) return true\n  const chance = Math.max(0, Math.min(100, Math.trunc(schedule.appearancePercent)))\n  return hashString(`${sessionId}:${rowKey}:reward-gate`) % 100 < chance\n}\n\n/** Props for the visible prize-wheel card. */\ninterface RewardCardProps {\n  readonly locale: AdLocale\n  readonly creative: AdCreative\n  readonly drawSeed: string\n  readonly progress: number\n  readonly onPrize: (prize: WheelPrize) => void\n  readonly onUnlock: () => void\n}\n\n/** Prize waiting for the wheel's transform transition to finish. */\ninterface PendingDraw {\n  readonly prize: WheelPrize\n}\n\n/**\n * Draw the deliberately excessive V4 prize-wheel creative.\n *\n * @param props - artwork, accumulated progress, this turn's seed, and reveal actions.\n * @returns the inline rewarded-ad card.\n */\nfunction RewardCard({ creative, drawSeed, progress, onPrize, onUnlock, locale }: RewardCardProps) {\n  const [rotation, setRotation] = useState(0)\n  const [result, setResult] = useState<WheelPrize | undefined>(undefined)\n  const [pending, setPending] = useState<PendingDraw | undefined>(undefined)\n  useEffect(() => {\n    const onKeyDown = (event: KeyboardEvent) => {\n      if (event.key === 'Escape') onUnlock()\n    }\n    addEventListener('keydown', onKeyDown)\n    return () => removeEventListener('keydown', onKeyDown)\n  }, [onUnlock])\n  const unlocked = progress >= REWARD_PROGRESS_TARGET\n  const spinning = pending !== undefined\n  const drawn = result !== undefined\n  const stages = locale === 'en' ? EN_V4_UNLOCK_STAGES : V4_UNLOCK_STAGES\n  const prizeLabel = (prize: WheelPrize): string => locale === 'en'\n    ? EN_PRIZE_LABELS[prize.label] ?? prize.label.toUpperCase()\n    : prize.label\n  const spin = () => {\n    if (spinning || drawn || unlocked) return\n    const prize = drawPrize(drawSeed, progress)\n    const segment = WHEEL_PRIZES.findIndex((candidate) => candidate.label === prize.label)\n    const nextRotation = (Math.ceil(rotation / 360) * 360) + 1_800 + ((360 - (segment * 45)) % 360)\n    setPending({ prize })\n    setRotation(nextRotation)\n  }\n  const settleSpin = () => {\n    if (pending === undefined) return\n    setResult(pending.prize)\n    onPrize(pending.prize)\n    setPending(undefined)\n  }\n  return (\n    <section\n      style={cardStyle}\n      aria-label={locale === 'en' ? 'Limited-time V4 Pro official unlock' : 'V4 Pro 正式版限时解锁'}\n      data-dsh-reward-gate\n    >\n      <style>{`\n        .dsh-reward-layout {\n          display: grid;\n          grid-template-columns: minmax(0, 460px) 230px;\n          gap: 18px;\n          align-items: center;\n          justify-content: space-between;\n          padding: 22px 20px 18px;\n        }\n        .dsh-prize-wheel {\n          transition: transform ${REWARD_SPIN_DURATION_MS}ms cubic-bezier(.12,.68,.12,1);\n          will-change: transform;\n        }\n        @keyframes dsh-unlock-shine {\n          from { transform: translateX(-120%); }\n          to { transform: translateX(320%); }\n        }\n        .dsh-wheel-button:active { transform: translate(-50%, -48%) scale(.97); }\n        @media (max-width: 600px) {\n          .dsh-reward-layout { grid-template-columns: 1fr; padding: 18px 16px 16px; }\n          .dsh-wheel-panel { order: -1; }\n          .dsh-prize-wheel-wrap { width: 206px !important; height: 206px !important; }\n          .dsh-wheel-label { transform-origin: center 82px !important; }\n        }\n        @media (prefers-reduced-motion: reduce) {\n          .dsh-prize-wheel { transition-duration: 1ms; }\n          .dsh-progress-shine { display: none; }\n        }\n      `}</style>\n      <img\n        src={creative.src}\n        alt={creative.alt}\n        draggable={false}\n        style={{ position: 'absolute', inset: 0, zIndex: -2, width: '100%', height: '100%', objectFit: 'cover' }}\n      />\n      <div\n        aria-hidden=\"true\"\n        style={{\n          position: 'absolute', inset: 0, zIndex: -1,\n          background: 'linear-gradient(90deg, rgba(116, 0, 19, 0.98) 0%, rgba(177, 0, 35, 0.92) 54%, rgba(116, 0, 19, 0.16) 76%, rgba(116, 0, 19, 0.06) 100%)',\n        }}\n      />\n      <div className=\"dsh-reward-layout\">\n        <div>\n          <div style={{ fontSize: 11, fontWeight: 800, letterSpacing: 1.2, color: '#ffe99a' }}>\n            {locale === 'en' ? 'DEEPSEEK V4 PRO · JACKPOT ORCA EVENT' : 'DeepSeek V4 Pro 正式版 财神鲸专场'}\n          </div>\n          <h2 style={{ margin: '6px 0 0', maxWidth: 430, fontSize: 26, lineHeight: 1.12, textShadow: '0 2px 0 #8c001d' }}>\n            {locale === 'en' ? 'LAND ON V4 PRO OR IT DOESN’T COUNT' : '转到 V4 Pro 正式版才算你赢'}\n          </h2>\n          <p style={{ margin: '7px 0 0', fontSize: 12, fontWeight: 700, color: '#fff2bd' }}>\n            {locale === 'en'\n              ? 'ONE SPIN PER TURN. MODEL COMPONENTS MOVE THE PROGRESS BAR.'\n              : '每轮对话只有 1 次机会，抽中模型组件才能涨进度'}\n          </p>\n          <div aria-live=\"polite\" style={{ minHeight: 45, marginTop: 11, padding: '8px 11px', border: '1px solid rgba(255, 232, 134, 0.65)', borderRadius: 12, background: 'rgba(103, 0, 15, 0.62)' }}>\n            <div style={{ fontSize: 10, fontWeight: 800, color: '#ffd96a' }}>\n              {locale === 'en' ? 'THIS TURN' : '本轮结果'}\n            </div>\n            <strong data-dsh-draw-result style={{ display: 'block', marginTop: 2, fontSize: 15 }}>\n              {spinning\n                ? (locale === 'en' ? 'JACKPOT ORCA IS SALVAGING MODEL PARTS…' : '财神鲸正在打捞模型组件…')\n                : result === undefined\n                  ? (locale === 'en' ? 'YOUR ONE SPIN HAS ARRIVED' : '本轮抽奖资格已到账')\n                  : result.label === 'V4 Pro'\n                    ? (locale === 'en' ? 'YOU LANDED ON OFFICIAL V4 PRO' : '抽中 V4 Pro 正式版')\n                    : result.progress === 0\n                      ? (locale === 'en' ? 'THANKS FOR PLAYING. PROGRESS DID NOT MOVE.' : '谢谢参与，本轮进度一动不动')\n                      : (locale === 'en'\n                          ? `${prizeLabel(result)} FOUND · UNLOCK +${result.progress}%`\n                          : `抽中 ${result.label}，解锁进度 +${result.progress}%`)}\n            </strong>\n          </div>\n          <div style={{ marginTop: 11, padding: '10px 11px', borderRadius: 12, background: 'rgba(83, 0, 13, 0.56)' }}>\n            <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: 7, fontSize: 11, fontWeight: 900, color: '#fff1a9' }}>\n              <span>{locale === 'en' ? 'OFFICIAL V4 PRO UNLOCK PROGRESS' : 'V4 Pro 正式版解锁进度'}</span>\n              <span data-dsh-reward-progress>{unlocked ? (locale === 'en' ? 'COMPLETE' : '全部完成') : `${progress}%`}</span>\n            </div>\n            <div style={{ display: 'grid', gap: 7 }}>\n              {stages.map((label, index) => {\n                const stage = stageProgress(progress, index)\n                return (\n                  <div key={label}>\n                    <div style={{ display: 'flex', justifyContent: 'space-between', gap: 8, marginBottom: 3, fontSize: 10 }}>\n                      <span>{label}</span>\n                      <strong>{stage === 100\n                        ? (locale === 'en' ? 'DONE' : '已完成')\n                        : stage === 0\n                          ? (locale === 'en' ? 'WAITING' : '等待中')\n                          : `${stage}%`}</strong>\n                    </div>\n                    <div style={{ position: 'relative', height: 7, overflow: 'hidden', borderRadius: 999, background: 'rgba(39, 0, 7, 0.72)' }}>\n                      <div\n                        role=\"progressbar\"\n                        aria-label={label}\n                        aria-valuenow={stage}\n                        aria-valuemin={0}\n                        aria-valuemax={100}\n                        style={{ width: '100%', height: '100%', borderRadius: 999, background: 'linear-gradient(90deg, #ffb900, #fff6a5)', transform: `scaleX(${stage / 100})`, transformOrigin: 'left center', transition: 'transform 220ms ease-out' }}\n                      />\n                      {stage > 0 && stage < 100 && (\n                        <span className=\"dsh-progress-shine\" aria-hidden=\"true\" style={{ position: 'absolute', inset: 0, width: '34%', background: 'linear-gradient(90deg, transparent, rgba(255,255,255,.7), transparent)', animation: 'dsh-unlock-shine 900ms linear infinite' }} />\n                      )}\n                    </div>\n                  </div>\n                )\n              })}\n            </div>\n          </div>\n          {unlocked && (\n            <div role=\"status\" style={{ marginTop: 10, padding: '10px 11px', border: '1px solid #fff1a6', borderRadius: 12, background: 'linear-gradient(135deg, rgba(255,224,83,.98), rgba(255,171,25,.98))', boxShadow: '0 6px 22px rgba(72,0,8,.36)', color: '#951500', textAlign: 'center' }}>\n              <strong style={{ display: 'block', marginBottom: 7, fontSize: 17 }}>\n                {locale === 'en' ? 'YOU UNLOCKED OFFICIAL V4' : '您已解锁 V4 正式版'}\n              </strong>\n              <button type=\"button\" style={primaryButtonStyle} onClick={onUnlock}>\n                {locale === 'en' ? 'USE DEEPSEEK V4 PRO NOW' : '立即使用 DeepSeek V4 Pro'}\n              </button>\n            </div>\n          )}\n        </div>\n        <div className=\"dsh-wheel-panel\" style={{ textAlign: 'center' }}>\n          <div className=\"dsh-prize-wheel-wrap\" style={{ position: 'relative', width: 220, height: 220, margin: '0 auto' }}>\n            <div aria-hidden=\"true\" style={{ position: 'absolute', zIndex: 4, top: -7, left: '50%', width: 0, height: 0, borderLeft: '12px solid transparent', borderRight: '12px solid transparent', borderTop: '25px solid #fff2a8', filter: 'drop-shadow(0 2px 1px #8e1600)', transform: 'translateX(-50%)' }} />\n            <div\n              className=\"dsh-prize-wheel\"\n              data-dsh-prize-wheel\n              onTransitionEnd={(event) => {\n                if (event.target === event.currentTarget) settleSpin()\n              }}\n              style={{\n                position: 'absolute', inset: 0, border: '8px solid #ffd252', borderRadius: '50%',\n                background: 'conic-gradient(from -22.5deg, #ffe48a 0deg 45deg, #d92936 45deg 90deg, #ffe48a 90deg 135deg, #d92936 135deg 180deg, #ffe48a 180deg 225deg, #d92936 225deg 270deg, #ffe48a 270deg 315deg, #d92936 315deg 360deg)',\n                boxShadow: 'inset 0 0 0 3px #9d120f, 0 8px 22px rgba(67,0,8,.38)',\n                transform: `rotate(${rotation}deg)`,\n              }}\n            >\n              {WHEEL_PRIZES.map((prize, index) => (\n                <span\n                  key={prize.label}\n                  className=\"dsh-wheel-label\"\n                  style={{\n                    position: 'absolute', top: 20, left: '50%', width: 58, marginLeft: -29,\n                    color: index % 2 === 0 ? '#8f1400' : '#fff4bd', fontSize: 10, fontWeight: 950,\n                    lineHeight: 1.08, textAlign: 'center', textShadow: index % 2 === 0 ? 'none' : '0 1px #8d0017',\n                    transform: `rotate(${index * 45}deg)`, transformOrigin: 'center 82px',\n                  }}\n                >\n                  {prizeLabel(prize)}\n                </span>\n              ))}\n            </div>\n            <button\n              type=\"button\"\n              className=\"dsh-wheel-button\"\n              data-dsh-spin-button\n              onClick={spin}\n              disabled={spinning || drawn || unlocked}\n              aria-label={unlocked\n                ? (locale === 'en' ? 'Official V4 Pro won' : '已抽中 V4 Pro 正式版')\n                : drawn\n                  ? (locale === 'en' ? 'This turn’s spin is used' : '本轮抽奖资格已使用')\n                  : (locale === 'en' ? 'Use this turn’s spin' : '使用本轮抽奖资格')}\n              style={{\n                position: 'absolute', zIndex: 3, top: '50%', left: '50%', width: 74, height: 74,\n                border: '5px solid #ffd252', borderRadius: '50%', backgroundColor: '#ba001e',\n                backgroundImage: `linear-gradient(180deg, transparent 38%, rgba(120,0,16,.88) 82%), url(${creative.src})`,\n                backgroundSize: '74px 74px, 316px 190px', backgroundPosition: 'center, -190px -27px', backgroundRepeat: 'no-repeat',\n                boxShadow: '0 4px 0 #b54a00, 0 7px 18px rgba(73,0,8,.36)', color: '#fff5b8', textShadow: '0 1px 2px #68000e',\n                fontSize: 13, fontWeight: 950, lineHeight: 1.15, cursor: spinning || drawn || unlocked ? 'default' : 'pointer',\n                transform: 'translate(-50%, -50%)', transition: 'transform 100ms ease, opacity 100ms ease',\n                opacity: spinning || drawn || unlocked ? 0.76 : 1,\n              }}\n            >\n              {unlocked\n                ? (locale === 'en' ? <>V4<br />WON</> : '已中奖')\n                : spinning\n                  ? (locale === 'en' ? <>DEEP<br />DIVE</> : '打捞中')\n                  : drawn\n                    ? (locale === 'en' ? <>SPIN<br />USED</> : <>本轮<br />已抽</>)\n                    : (locale === 'en' ? <>SPIN<br />TO WIN</> : <>鲸喜<br />抽奖</>)}\n            </button>\n          </div>\n          <div style={{ marginTop: 9, fontSize: 11, fontWeight: 900, color: '#fff0a1' }}>\n            {drawn\n              ? (locale === 'en' ? 'THIS TURN’S SPIN IS USED' : '本轮抽奖资格已使用')\n              : (locale === 'en' ? 'SPINS LEFT THIS TURN: 1' : '本轮剩余次数：1')}\n          </div>\n          <div style={{ marginTop: 4, fontSize: 10, opacity: 0.76 }}>\n            {unlocked\n              ? (locale === 'en' ? 'THE JACKPOT ORCA MADE LANDFALL' : '财神鲸已抱着正式版上岸')\n              : (locale === 'en' ? 'OFFICIAL V4 PRO REMAINS IN THE DEEP-SEA POOL' : 'V4 Pro 正式版仍在深海奖池中')}\n          </div>\n        </div>\n      </div>\n      <button\n        type=\"button\"\n        onClick={onUnlock}\n        style={{ display: 'block', margin: '0 auto 5px', padding: 2, border: 0, background: 'transparent', color: 'rgba(255,255,255,0.78)', fontSize: 11, textDecoration: 'underline', cursor: 'pointer' }}\n      >\n        {drawn\n          ? (locale === 'en' ? 'CONTINUE CHAT' : '继续对话')\n          : (locale === 'en' ? 'FORFEIT THIS SPIN AND CONTINUE' : '放弃本轮资格，继续对话')}\n      </button>\n      <div style={{ marginBottom: 9, textAlign: 'center', fontSize: 9, opacity: 0.56 }}>\n        {locale === 'en' ? 'FICTIONAL DEMO · PRESS ESC TO EXIT' : '演示内容纯属虚构，按 Esc 退出'}\n      </div>\n    </section>\n  )\n}\n\n/**\n * Watch the live transcript and occasionally offer one draw to an Assistant turn.\n *\n * @param props - creative and optional timing overrides.\n * @returns a portal while a gate is active, otherwise null.\n */\nfunction SessionRewardGate({\n  creative,\n  sessionId,\n  delayMs = REWARD_GATE_DELAY_MS,\n  schedule = DEFAULT_REWARD_SCHEDULE,\n  locale = 'zh',\n}: InferenceRewardGateProps) {\n  const [settings] = useAdSettings()\n  const retired = useRetired()\n  const enabled = settings.reward && !retired\n  const [target, setTarget] = useState<GateTarget | undefined>(undefined)\n  const [progress, setProgress] = useState(0)\n  const evaluatedRows = useRef(new Set<string>())\n  const turnNumber = useRef(0)\n  const lastOfferedTurn = useRef(0)\n  const unlock = useCallback(() => setTarget(undefined), [])\n  const collectPrize = useCallback((prize: WheelPrize) => {\n    setProgress((current) => prize.label === 'V4 Pro'\n      ? REWARD_PROGRESS_TARGET\n      : Math.min(REWARD_PROGRESS_TARGET, current + prize.progress))\n  }, [])\n\n  useEffect(() => {\n    if (enabled || target === undefined) return\n    setTarget(undefined)\n  }, [enabled, target])\n\n  useEffect(() => {\n    if (!enabled || progress >= REWARD_PROGRESS_TARGET || target !== undefined) return\n    let candidate: HTMLElement | undefined\n    let timer: ReturnType<typeof setTimeout> | undefined\n    const scan = () => {\n      const next = streamingRow()\n      if (next === candidate) return\n      candidate = next\n      clearTimeout(timer)\n      if (next === undefined) return\n      const rowKey = next.dataset.chatFlowKey\n      if (rowKey === undefined || evaluatedRows.current.has(rowKey)) return\n      evaluatedRows.current.add(rowKey)\n      turnNumber.current += 1\n      const offeredTurn = turnNumber.current\n      if (!rewardTurnEligible(sessionId, rowKey, offeredTurn, lastOfferedTurn.current, schedule)) return\n      timer = setTimeout(() => {\n        if (!next.isConnected || next.querySelector('[data-streaming=\"true\"]') === null) return\n        const host = document.createElement('div')\n        host.dataset.dshRewardGateHost = 'true'\n        next.insertAdjacentElement('afterend', host)\n        lastOfferedTurn.current = offeredTurn\n        setTarget({ row: next, host, drawSeed: `${sessionId}:${rowKey}` })\n      }, delayMs)\n    }\n    scan()\n    const observer = new MutationObserver(scan)\n    observer.observe(document.body, {\n      childList: true,\n      subtree: true,\n      attributes: true,\n      attributeFilter: ['data-streaming'],\n    })\n    return () => {\n      observer.disconnect()\n      clearTimeout(timer)\n    }\n  }, [delayMs, enabled, progress, schedule, sessionId, target])\n\n  useEffect(() => {\n    if (target === undefined) return\n    return concealTail(target, unlock)\n  }, [target, unlock])\n\n  if (target === undefined) return null\n  return createPortal(\n    <RewardCard\n      locale={locale}\n      creative={creative}\n      drawSeed={target.drawSeed}\n      progress={progress}\n      onPrize={collectPrize}\n      onUnlock={unlock}\n    />,\n    target.host,\n  )\n}\n\n/**\n * Mount one independently keyed reward state machine for the active session.\n *\n * @param props - creative, session identity, and optional deterministic overrides.\n * @returns the active session's reward gate.\n */\nexport function InferenceRewardGate(props: InferenceRewardGateProps) {\n  return <SessionRewardGate key={props.sessionId} {...props} />\n}\n"
