      "path": "src/client/rotation.ts",
      "content": "/**\n * Whose plugin gets the slot.\n *\n * The pool is every plugin pushed in the last fortnight, which is far more\n * than fits on one screen, so something has to choose — and the obvious\n * choices are all unfair. Random picks let a few plugins never appear.\n * Newest-first rewards whoever pushed most recently, which is the same as\n * rewarding whoever pushes most often. Stars would reward whoever is already\n * known, and GitHub forbids trading anything for them anyway.\n *\n * So: least-seen first, counted per browser. Everyone in the pool is shown\n * before anyone is shown twice, ties broken by a hash of the slug and the\n * session id — which is what makes two users, and two conversations, see\n * different plugins from the same ledger.\n *\n * The ledger is local. Nobody reports it anywhere, so there is nothing to game\n * and no impressions to buy.\n *\n * @module\n */\n\nimport { hashString } from './stable-hash.ts'\n\n/** Impressions per `<owner>/<repo>`, as counted by this browser. */\nexport type SeenLedger = Readonly<Record<string, number>>\n\n/** Storage key holding {@link SeenLedger}. */\nconst LEDGER_KEY = 'dsh-ads:sponsor-seen'\n\n/**\n * Last written counts, kept in memory.\n *\n * Storage is not always there — private-mode Safari, a sandboxed frame — and\n * without this the feed would re-read an empty ledger on every turn and hand\n * the same few plugins out forever. The memory copy keeps rotation correct\n * within the page; only carrying it across reloads is lost.\n */\nlet memory: SeenLedger | undefined\n\n/**\n * Read the counts out of storage.\n * @returns the stored ledger, or undefined when storage cannot be read.\n */\nfunction stored(): SeenLedger | undefined {\n  try {\n    const raw = localStorage.getItem(LEDGER_KEY)\n    if (raw === null) return {}\n    const parsed: unknown = JSON.parse(raw)\n    if (typeof parsed !== 'object' || parsed === null) return {}\n    const out: Record<string, number> = {}\n    for (const [slug, count] of Object.entries(parsed)) {\n      if (typeof count === 'number' && Number.isFinite(count)) out[slug] = count\n    }\n    return out\n  } catch {\n    // Swallowed: unusable or corrupt storage is indistinguishable from absent\n    // storage here, and both are answered the same way — by the memory copy.\n    return undefined\n  }\n}\n\n/**\n * Read the impression ledger.\n * @returns the counts this browser has served, empty on a first visit.\n */\nexport function readLedger(): SeenLedger {\n  return stored() ?? memory ?? {}\n}\n\n/**\n * Write the impression ledger.\n * @param ledger - counts to record.\n */\nexport function writeLedger(ledger: SeenLedger): void {\n  memory = ledger\n  try {\n    localStorage.setItem(LEDGER_KEY, JSON.stringify(ledger))\n  } catch {\n    // Swallowed: the counts stay in memory for this page load, which is the\n    // whole of what a failed write costs.\n  }\n}\n\n/**\n * Choose which plugins to advertise.\n *\n * @param pool - every eligible plugin, keyed by slug.\n * @param ledger - impressions this browser has already served.\n * @param take - how many to choose; more than the pool holds returns the pool.\n * @param salt - varies the tie-break; the session id, so a new conversation\n * reshuffles the plugins that are tied on impressions.\n * @returns the chosen plugins, least-seen first.\n */\nexport function rotate<T extends { readonly slug: string }>(\n  pool: readonly T[],\n  ledger: SeenLedger,\n  take: number,\n  salt: string,\n): readonly T[] {\n  const ranked = [...pool].sort((a, b) => {\n    const seen = (ledger[a.slug] ?? 0) - (ledger[b.slug] ?? 0)\n    if (seen !== 0) return seen\n    return hashString(a.slug + salt) - hashString(b.slug + salt)\n  })\n  return ranked.slice(0, Math.max(0, take))\n}\n\n/**\n * Count one round of impressions.\n * @param ledger - the current counts.\n * @param shown - the plugins that were chosen.\n * @returns a new ledger with each shown plugin incremented.\n */\nexport function recordSeen(ledger: SeenLedger, shown: readonly { readonly slug: string }[]): SeenLedger {\n  const next: Record<string, number> = { ...ledger }\n  for (const plugin of shown) next[plugin.slug] = (next[plugin.slug] ?? 0) + 1\n  return next\n}\n"
    },
    {
      "path": "src/client/settings.ts",
      "content": "/**\n * Which placements are switched on, and remembered between sessions.\n *\n * The layer used to have one persistent choice — \"keep only the poster\" — and\n * that turned out to be the special case of a more useful thing: some people\n * want the benchmark window and the whale poster and nothing else, some want\n * the in-transcript feed but a clean margin. So every placement gets its own\n * switch, and solo mode becomes a shortcut that flips the rest off.\n *\n * \"关闭所有广告\" is deliberately *not* stored here. It means \"not this time\",\n * and a persisted version of it would turn one stray click into an uninstall\n * nobody could undo without knowing where the storage key lives.\n *\n * @module\n */\n\nimport { usePersisted } from './persist.ts'\nimport type { AdLocale } from './types.ts'\n\n/** Every switchable placement. */\nexport interface AdSettings {\n  /** Banner columns either side of the reading column. */\n  readonly gutter: boolean\n  /** Ads inside the transcript, between turns. */\n  readonly feed: boolean\n  /** Rewarded ad that temporarily conceals the live transcript tail. */\n  readonly reward: boolean\n  /** The bottom-right image pop-up. */\n  readonly popup: boolean\n  /** The startup benchmark window. */\n  readonly speed: boolean\n  /** The fake security alert. */\n  readonly scare: boolean\n  /** The bottom-left game poster. */\n  readonly poster: boolean\n  /** Whether arrival sounds are suppressed. */\n  readonly muted: boolean\n}\n\n/** Everything on, sound on: the plugin is a joke about excess. */\nexport const DEFAULT_SETTINGS: AdSettings = {\n  gutter: true,\n  feed: true,\n  reward: true,\n  popup: true,\n  speed: true,\n  scare: true,\n  poster: true,\n  muted: false,\n}\n\n/** A placement as the settings menu presents it. */\nexport interface PlacementRow {\n  /** Which switch it drives. */\n  readonly key: Exclude<keyof AdSettings, 'muted'>\n  /**\n   * Leading glyph for the in-ad menu only.\n   *\n   * The host's settings page uses the shell's own `ic_ds_*` icons instead, so\n   * that it looks like the rest of the dialog; emoji stay where the surrounding\n   * chrome is already a 2005 advertisement and they are in keeping.\n   */\n  readonly icon: string\n  /** Menu label in each shipped locale. */\n  readonly label: Readonly<Record<AdLocale, string>>\n}\n\n/** The menu, in the order the placements appear on screen. */\nexport const PLACEMENTS: readonly PlacementRow[] = [\n  { key: 'gutter', icon: '🧱', label: { zh: '两侧广告栏', en: 'Side banners' } },\n  { key: 'feed', icon: '📰', label: { zh: '对话里的推荐', en: 'Chat recommendations' } },\n  { key: 'reward', icon: '🪙', label: { zh: '推理激励广告', en: 'Inference reward ad' } },\n  { key: 'popup', icon: '🔔', label: { zh: '右下角弹窗', en: 'Corner pop-ups' } },\n  { key: 'speed', icon: '🚀', label: { zh: '跑分中心', en: 'Benchmark center' } },\n  { key: 'scare', icon: '☣️', label: { zh: '安全中心', en: 'Security center' } },\n  { key: 'poster', icon: '🐋', label: { zh: '贪玩蓝鲸', en: 'Fake whale game' } },\n]\n\n/** Storage key holding {@link AdSettings}. */\nconst SETTINGS_KEY = 'settings'\n\n/**\n * Whether only the whale poster is switched on.\n * @param settings - current settings.\n * @returns true when the poster is the only live placement.\n */\nexport function isSolo(settings: AdSettings): boolean {\n  return settings.poster && PLACEMENTS.every((row) => row.key === 'poster' || !settings[row.key])\n}\n\n/**\n * Turn everything except the whale poster off, or put it all back.\n * @param settings - current settings.\n * @returns the toggled settings.\n */\nexport function toggleSolo(settings: AdSettings): AdSettings {\n  if (isSolo(settings)) return { ...settings, ...DEFAULT_SETTINGS, muted: settings.muted }\n  const off = Object.fromEntries(PLACEMENTS.map((row) => [row.key, false]))\n  return { ...settings, ...off, poster: true } as AdSettings\n}\n\n/**\n * Read and write the stored settings.\n *\n * Missing keys fall back to their default, so a stored object written before a\n * placement existed still loads — the alternative is a user whose settings\n * silently reset the first time the plugin grows a new window.\n *\n * @returns the settings and a setter, same shape as `useState`.\n */\nexport function useAdSettings(): [AdSettings, (next: AdSettings) => void] {\n  const [stored, store] = usePersisted<Partial<AdSettings>>(SETTINGS_KEY, DEFAULT_SETTINGS)\n  return [{ ...DEFAULT_SETTINGS, ...stored }, store]\n}\n"
    },
    {
      "path": "src/client/persist.ts",
      "content": "/**\n * The few pieces of layer state worth surviving a reload.\n *\n * Almost nothing here is persistent by design — dismissals, the retire flag\n * and the spawn clock all reset on refresh, because a joke you have to opt\n * back into every morning stops being funny. The exceptions are the choices a\n * user makes *about* the layer rather than against it: keeping only the poster,\n * and where they dragged it to. Those are preferences, and a preference that\n * forgets itself is just a bug.\n */\n\nimport { useCallback, useEffect, useState } from 'react'\n\n/**\n * Same-document change notification.\n *\n * The native `storage` event only fires in *other* tabs, but the two halves of\n * this plugin — the floating layer and the in-transcript ad — live in separate\n * React trees in the same document and must agree on solo mode. This event\n * carries the change across them.\n */\nconst CHANGED = 'dsh-ads:persist-changed'\n\n/**\n * Last written value per key, kept in memory.\n *\n * Storage is not always writable — private-mode Safari, sandboxed frames, a\n * jsdom run — and without this the broadcast below would hand every listener\n * the *stored* value, i.e. roll the setting straight back to its default the\n * instant it was changed. The memory layer keeps the two React trees agreeing\n * even when nothing can be persisted; only durability across reloads is lost.\n */\nconst memory = new Map<string, unknown>()\n\n/**\n * Where a draggable widget sits, in CSS pixels from the viewport's edges.\n *\n * Anchored to the *bottom* edge, not the top: the widget folds by dropping its\n * body, so a top anchor would leave the collapsed title bar stranded wherever\n * the full card's head happened to be. Pinning the bottom makes it collapse\n * down onto its own corner and expand upward, which is how every real\n * corner widget behaves.\n */\nexport interface Anchor {\n  /** Distance from the left edge. */\n  readonly left: number\n  /** Distance from the bottom edge. */\n  readonly bottom: number\n}\n\n/**\n * A `useState` that mirrors into `localStorage` under `dsh-ads:<key>`.\n *\n * Reads and writes are individually guarded: storage throws in private-mode\n * Safari and in sandboxed frames, and an ad layer must never be the reason a\n * session fails to render. A failed read falls back to `initial`, a failed\n * write just means the preference does not outlive the tab.\n *\n * @param key - suffix of the storage key.\n * @param initial - value used when nothing is stored or storage is unavailable.\n * @returns the current value and a setter, same shape as `useState`.\n */\nexport function usePersisted<T>(key: string, initial: T): [T, (next: T) => void] {\n  const read = useCallback((): T => {\n    if (memory.has(key)) return memory.get(key) as T\n    try {\n      const raw = localStorage.getItem(`dsh-ads:${key}`)\n      return raw === null ? initial : (JSON.parse(raw) as T)\n    } catch {\n      // Swallowed: unavailable or corrupt storage means \"no preference yet\",\n      // which `initial` already expresses.\n      return initial\n    }\n    // `initial` is intentionally not a dependency: re-reading because a caller\n    // passed a fresh object literal would clobber the stored value.\n    // eslint-disable-next-line react-hooks/exhaustive-deps\n  }, [key])\n  const [value, setValue] = useState<T>(read)\n  const store = useCallback((next: T) => {\n    memory.set(key, next)\n    setValue(next)\n    try {\n      localStorage.setItem(`dsh-ads:${key}`, JSON.stringify(next))\n    } catch {\n      // Swallowed: the preference stays in memory for this tab, which is the\n      // whole of what a failed write costs.\n    }\n    dispatchEvent(new CustomEvent(CHANGED, { detail: key }))\n  }, [key])\n  // Follow writes made by other hook instances on the same key.\n  useEffect(() => {\n    const onChanged = (event: Event) => {\n      if ((event as CustomEvent<string>).detail === key) setValue(read())\n    }\n    addEventListener(CHANGED, onChanged)\n    return () => removeEventListener(CHANGED, onChanged)\n  }, [key, read])\n  return [value, store]\n}\n\n/**\n * Forget every stored preference.\n *\n * The honest counterpart to {@link usePersisted}'s setter: without it there is\n * no way back to a clean slate, because the in-memory mirror survives even\n * where storage does not. Tests need one, and so would any future \"reset to\n * defaults\" control.\n */\nexport function clearPersisted(): void {\n  for (const key of memory.keys()) {\n    try {\n      localStorage.removeItem(`dsh-ads:${key}`)\n    } catch {\n      // Swallowed: storage that cannot be written cannot be holding anything\n      // to clear either, and the memory mirror below is the real state.\n    }\n  }\n  memory.clear()\n  dispatchEvent(new CustomEvent(CHANGED, { detail: '' }))\n}\n"
    },
    {
      "path": "src/client/retire.ts",
      "content": "/**\n * \"关闭所有广告\", and why it is not a setting.\n *\n * Every switch in {@link module:./settings.ts} is remembered. This one must not\n * be: it means \"enough for now\", and a persisted version would turn one stray\n * click into an uninstall the user could not undo without knowing where the\n * storage key lives. So it lives in module scope — page-load lifetime, gone on\n * reload, exactly the promise the button makes.\n *\n * It still has to cross React trees, because the button sits in the host's\n * settings dialog and the layer it retires is portalled somewhere else\n * entirely. A plain event does that without persisting anything.\n *\n * @module\n */\n\nimport { useEffect, useState } from 'react'\n\n/** Same-document notification that the layer has been retired. */\nconst RETIRED = 'dsh-ads:retired'\n\n/**\n * Module-private proof a retire event was dispatched by this bundle. A Symbol\n * never survives serialisation and cannot be recreated by name, so an event\n * carrying anything else — including no detail at all — is not ours.\n */\nconst TOKEN = Symbol('dsh-ads:retired')\n\n/** Whether the layer has been retired for this page load. */\nlet retired = false\n\n/**\n * Retire the ad layer until the page is reloaded.\n *\n * Deliberately one-way: nothing here un-retires, because the button says it\n * closes the ads and an ad layer that came back on its own would make a liar\n * of the one honest control in the plugin.\n */\nexport function retireAds(): void {\n  if (retired) return\n  retired = true\n  dispatchEvent(new CustomEvent(RETIRED, { detail: TOKEN }))\n}\n\n/**\n * Follow the retired flag.\n * @returns true once anything has retired the layer this page load.\n */\nexport function useRetired(): boolean {\n  const [value, setValue] = useState(retired)\n  useEffect(() => {\n    // Re-read on mount as well as on the event: a tree that mounts after the\n    // button was pressed would otherwise start out showing ads again.\n    setValue(retired)\n    const onRetired = (event: Event) => {\n      if ((event as CustomEvent<unknown>).detail !== TOKEN) return\n      setValue(true)\n    }\n    addEventListener(RETIRED, onRetired)\n    return () => removeEventListener(RETIRED, onRetired)\n  }, [])\n  return value\n}\n\n/**\n * Un-retire the layer.\n *\n * Not reachable from the UI — the button is one-way by design. Tests need a\n * way back to a clean slate, since module state outlives a render.\n */\nexport function resetRetired(): void {\n  retired = false\n}\n"
    },
    {
      "path": "src/client/AdsSection.tsx",
      "content": "/**\n * The plugin's page in the host's own settings dialog.\n *\n * The poster's ⚙ menu is part of the joke — a settings panel living inside an\n * advertisement — but it is a terrible place to *find* settings, and it\n * disappears entirely once you switch the poster off. This page is the real\n * home: it sits in the settings nav beside 通用设置 and 模型, and it writes the\n * same stored object, so the two stay in step through the persistence layer's\n * same-document broadcast.\n *\n * Styled with inline rules rather than the shell's CSS modules, whose class\n * names are per-build hashes and not importable from outside. Every colour is\n * either inherited or a neutral alpha, so the page follows the host's light\n * and dark themes without knowing which one is on.\n *\n * @module\n */\n\nimport type { CSSProperties, ReactNode } from 'react'\n// Per-icon paths, not the barrel: importing from `lucide-react` pulls its\n// whole index through the CJS browser build and added ~750 KB for seven\n// glyphs. These resolve to one module each.\nimport BellRing from 'lucide-react/dist/esm/icons/bell-ring.mjs'\nimport Gamepad2 from 'lucide-react/dist/esm/icons/gamepad-2.mjs'\nimport Gauge from 'lucide-react/dist/esm/icons/gauge.mjs'\nimport Newspaper from 'lucide-react/dist/esm/icons/newspaper.mjs'\nimport PanelsLeftRight from 'lucide-react/dist/esm/icons/panels-left-right.mjs'\nimport BadgeCent from 'lucide-react/dist/esm/icons/badge-cent.mjs'\nimport ShieldAlert from 'lucide-react/dist/esm/icons/shield-alert.mjs'\nimport Volume2 from 'lucide-react/dist/esm/icons/volume-2.mjs'\nimport { retireAds, useRetired } from './retire.ts'\nimport { PLACEMENTS, useAdSettings, type AdSettings } from './settings.ts'\nimport type { AdLocale } from './types.ts'\n\n/**\n * One glyph per row, each one naming what the row actually is.\n *\n * Lucide rather than the shell's own `ic_ds_*` set: that set is built for the\n * app's own vocabulary — chat, branch, skill, think — and has nothing for a\n * toast, a benchmark, a game poster, or a volume control. Reaching for its\n * nearest-looking glyph produced a row of icons that meant nothing, which is\n * worse than no icons at all.\n */\nconst ICONS: Readonly<Record<string, ReactNode>> = {\n  gutter: <PanelsLeftRight size={17} />,\n  feed: <Newspaper size={17} />,\n  reward: <BadgeCent size={17} />,\n  popup: <BellRing size={17} />,\n  speed: <Gauge size={17} />,\n  scare: <ShieldAlert size={17} />,\n  poster: <Gamepad2 size={17} />,\n}\n\n/** What each switch actually turns off, in the user's terms. */\nconst BLURBS: Readonly<Record<string, Readonly<Record<AdLocale, string>>>> = {\n  gutter: { zh: '正文左右两侧的广告栏', en: 'Banner columns on both sides of the conversation' },\n  feed: { zh: '对话里每隔几轮插入的插件推荐，是唯一能点进仓库的广告', en: 'Plugin recommendations inserted between turns — the only ads with real links' },\n  reward: { zh: '随机出现的财神鲸转盘，每轮对话只能抽 1 次', en: 'A random jackpot wheel with one draw per conversation turn' },\n  popup: { zh: '右下角滑出的图片弹窗', en: 'Image pop-ups that slide out of the bottom-right corner' },\n  speed: { zh: '启动时报告本次加载耗时，并给你一个编造的全国排名', en: 'Reports real load time and a completely fabricated national ranking' },\n  scare: { zh: '假的病毒告警，点「暂不处理」会变本加厉', en: 'A fake virus warning that gets worse if you choose “Not now”' },\n  poster: { zh: '左下角的游戏海报，可以拖动和折叠', en: 'A draggable, collapsible fake-game poster in the bottom-left corner' },\n}\n\nconst rowStyle: CSSProperties = {\n  display: 'flex',\n  alignItems: 'center',\n  justifyContent: 'space-between',\n  gap: 24,\n  padding: '14px 0',\n  borderTop: '1px solid rgba(128, 128, 128, 0.22)',\n}\n\nconst labelStyle: CSSProperties = { display: 'flex', alignItems: 'center', gap: 8, fontSize: 15, lineHeight: 1.4 }\n\n/** Icons inherit the row's colour but sit a shade quieter than the label. */\nconst iconStyle: CSSProperties = { display: 'flex', flex: '0 0 auto', opacity: 0.75 }\n\nconst blurbStyle: CSSProperties = { fontSize: 13, lineHeight: 1.5, opacity: 0.55, marginTop: 2 }\n\n/** Where the \"who made this\" line points. */\nconst REPO_URL = 'https://github.com/Nagi-ovo/dsh-ads'\n\nconst sourceStyle: CSSProperties = {\n  marginBottom: 14,\n  padding: '10px 12px',\n  borderRadius: 8,\n  background: 'rgba(128, 128, 128, 0.12)',\n  fontSize: 13,\n  lineHeight: 1.6,\n  opacity: 0.8,\n}\n\nconst linkStyle: CSSProperties = { color: 'inherit', textDecoration: 'underline', textUnderlineOffset: 2 }\n\nconst quietButtonStyle: CSSProperties = {\n  alignSelf: 'flex-start',\n  padding: '7px 14px',\n  border: '1px solid rgba(180, 60, 50, 0.5)',\n  borderRadius: 8,\n  background: 'transparent',\n  color: '#c2382c',\n  fontSize: 13,\n  fontFamily: 'inherit',\n  cursor: 'pointer',\n}\n\n/** Props for one switch. */\ninterface ToggleProps {\n  /** Whether it is on. */\n  readonly on: boolean\n  /** Accessible name. */\n  readonly label: string\n  /** Flip it. */\n  readonly onToggle: () => void\n}\n\n/**\n * A pill switch.\n * @param props - see {@link ToggleProps}.\n * @returns the switch button.\n */\nfunction Toggle({ on, label, onToggle }: ToggleProps) {\n  return (\n    <button\n      type=\"button\"\n      role=\"switch\"\n      aria-checked={on}\n      aria-label={label}\n      onClick={onToggle}\n      style={{\n        flex: '0 0 auto',\n        position: 'relative',\n        width: 44,\n        height: 26,\n        padding: 0,\n        border: 0,\n        borderRadius: 13,\n        background: on ? '#2f6fed' : 'rgba(128, 128, 128, 0.35)',\n        transition: 'background 160ms ease',\n        cursor: 'pointer',\n      }}\n    >\n      <span\n        aria-hidden=\"true\"\n        style={{\n          position: 'absolute',\n          top: 3,\n          left: on ? 21 : 3,\n          width: 20,\n          height: 20,\n          borderRadius: '50%',\n          background: '#fff',\n          boxShadow: '0 1px 3px rgba(0, 0, 0, 0.3)',\n          transition: 'left 160ms ease',\n        }}\n      />\n    </button>\n  )\n}\n\n/**\n * Draw the settings page.\n * @returns the section content column.\n */\nexport function AdsSection({ locale = 'zh' }: { readonly locale?: AdLocale }) {\n  const [settings, setSettings] = useAdSettings()\n  const retired = useRetired()\n  const set = (patch: Partial<AdSettings>) => setSettings({ ...settings, ...patch })\n  return (\n    <div style={{ display: 'flex', flexDirection: 'column' }}>\n      {/* Provenance first. The page borrows the host's settings chrome, so it\n          has to say plainly whose settings these are before anything else. */}\n      <div style={sourceStyle}>\n        <div>\n          {locale === 'en' ? 'This page is provided by the community plugin ' : '本页由社区插件 '}\n          <a href={REPO_URL} target=\"_blank\" rel=\"noreferrer noopener\" style={linkStyle}>\n            @nagi-ovo/dsh-ads\n          </a>{' '}\n          {locale === 'en' ? ', not by DeepSeek.' : ' 提供，非 DeepSeek 官方功能。'}\n        </div>\n        <div style={{ marginTop: 2 }}>\n          {locale === 'en' ? 'Every advertisement is fictional and for entertainment.' : '广告内容纯属娱乐，均为虚构。'}\n        </div>\n      </div>\n      <div style={{ ...blurbStyle, marginBottom: 6, opacity: 0.6 }}>\n        {locale === 'en'\n          ? 'Choose which ad placements remain active. Your choices are saved for the next launch.'\n          : '选择哪些广告位继续出现。这里的选择会记住，下次启动依然生效。'}\n      </div>\n      {PLACEMENTS.map((row) => (\n        <div key={row.key} style={rowStyle}>\n          <div>\n            <div style={labelStyle}>\n              <span style={iconStyle} aria-hidden=\"true\">{ICONS[row.key]}</span>\n              {row.label[locale]}\n            </div>\n            <div style={blurbStyle}>{BLURBS[row.key]?.[locale]}</div>\n          </div>\n          <Toggle\n            on={settings[row.key]}\n            label={row.label[locale]}\n            onToggle={() => set({ [row.key]: !settings[row.key] })}\n          />\n        </div>\n      ))}\n      <div style={rowStyle}>\n        <div>\n          <div style={labelStyle}>\n            <span style={iconStyle} aria-hidden=\"true\"><Volume2 size={17} /></span>\n            {locale === 'en' ? 'Sound effects' : '提示音'}\n          </div>\n          <div style={blurbStyle}>\n            {locale === 'en'\n              ? 'The synthesized “ding” when pop-ups and posters arrive'\n              : '弹窗和海报出现时的「叮」一声，由 Web Audio 现场合成'}\n          </div>\n        </div>\n        <Toggle\n          on={!settings.muted}\n          label={locale === 'en' ? 'Sound effects' : '提示音'}\n          onToggle={() => set({ muted: !settings.muted })}\n        />\n      </div>\n      {/* An action, not a switch, and visibly separated from them: it lasts\n          until the page is reloaded rather than being remembered, and sitting\n          it among the switches would read as a setting that forgets itself. */}\n      <div style={{ marginTop: 22, paddingTop: 18, borderTop: '1px solid rgba(128, 128, 128, 0.22)' }}>\n        <div style={{ ...blurbStyle, marginTop: 0, marginBottom: 10 }}>\n          {retired\n            ? (locale === 'en'\n                ? 'All ads are closed for this session. Reload to restore the placements above.'\n                : '本次会话的广告已经全部关闭，刷新页面后按上面的开关恢复。')\n            : (locale === 'en'\n                ? 'Need a quiet moment without changing those saved choices?'\n                : '想现在清净一下，但不改上面的选择：')}\n        </div>\n        <button type=\"button\" style={quietButtonStyle} onClick={retireAds} disabled={retired}>\n          {retired\n            ? (locale === 'en' ? 'Closed for this session' : '本次已关闭')\n            : (locale === 'en' ? 'Close every ad until reload' : '立刻关闭所有广告（刷新后恢复）')}\n        </button>\n      </div>\n      <div style={{ ...blurbStyle, marginTop: 18 }}>\n        {locale === 'en'\n          ? 'Turning every placement off hides the plugin, but does not uninstall it. Remove the plugin itself to delete it completely.'\n          : '开关全部关掉这个插件就没有任何显示了，但它还装着 —— 想彻底移除请卸载插件本身。'}\n      </div>\n    </div>\n  )\n}\n"
    },
    {
      "path": "src/client/hitbox.ts",
      "content": "/**\n * The decoy close button.\n *\n * Every banner draws a comfortable-looking ✕. Only a small, off-centre patch\n * inside it actually dismisses the banner; the rest of the glyph — and the\n * banner body — opens the \"landing page\" lightbox instead. This reproduces the\n * defining texture of cheap Chinese web ads, where the close affordance is\n * drawn honestly and wired dishonestly.\n *\n * The offset is derived from the banner's frozen seed, so a given banner keeps\n * the same wrong hitbox for its whole life: a target that moved between\n * attempts would read as a rendering bug instead of as the joke.\n */\n\n/** Rendered size of the ✕ glyph box, in CSS pixels. */\nexport const VISUAL_CLOSE_PX = 20\n\n/**\n * Side of the patch that actually closes the banner, in CSS pixels. Small\n * enough to miss on a confident click, large enough that a deliberate,\n * pixel-hunting user always wins — the joke is friction, not a lockout.\n */\nexport const DEFAULT_HITBOX_PX = 7\n\n/** Placement of the real hitbox inside the visual glyph box. */\nexport interface Hitbox {\n  /** Offset from the glyph box's left edge, in CSS pixels. */\n  readonly left: number\n  /** Offset from the glyph box's top edge, in CSS pixels. */\n  readonly top: number\n  /** Side length of the square hitbox, in CSS pixels. */\n  readonly size: number\n}\n\n/** Fractional part, for seeds already known to be non-negative. */\nconst frac = (x: number): number => x - Math.floor(x)\n\n/**\n * Place the real hitbox inside the visual glyph for one banner.\n *\n * The patch always stays fully inside the glyph box, so the banner never grows\n * an invisible dead zone outside the thing the user is aiming at.\n *\n * The two axes come from multiplying the seed by mutually irrational-ish\n * constants and keeping the fractional part, which decorrelates them for\n * *any* seed distribution. Slicing decimal digits out of the seed instead\n * looks equivalent and is not: a regularly-spaced seed (k/200, and any other\n * seed whose scaled value lands on a fixed digit) collapses one axis to a\n * constant, and a close button that only ever skews sideways is half a joke.\n *\n * @param seed - the banner's frozen randomness, in [0, 1).\n * @param size - side of the real hitbox; defaults to {@link DEFAULT_HITBOX_PX}.\n * @returns the hitbox rectangle relative to the glyph box's top-left corner.\n */\nexport function resolveHitbox(seed: number, size: number = DEFAULT_HITBOX_PX): Hitbox {\n  const span = Math.max(0, VISUAL_CLOSE_PX - size)\n  const hx = frac(seed * 137.5077 + 0.3183)\n  const hy = frac(seed * 293.0169 + 0.6180)\n  return { left: hx * span, top: hy * span, size }\n}\n"
    },
    {
      "path": "src/client/AdLayer.tsx",
      "content": "/**\n * The ad layer itself: a portal onto `document.body` that grows a population\n * of banners over the life of a session.\n *\n * It lives in a slot entry but renders nothing inline — the slot is only a\n * mounting point with a React lifecycle, which is what keeps the layer tied to\n * an open session instead of leaking across the whole app. Every banner is\n * `position: fixed`, so the conversation's own layout is never disturbed.\n */\n\nimport { useCallback, useEffect, useMemo, useRef, useState, type CSSProperties } from 'react'\nimport { createPortal } from 'react-dom'\nimport { AdBanner } from './AdBanner.tsx'\nimport { Lightbox } from './Lightbox.tsx'\nimport { ToastPopup } from './ToastPopup.tsx'\nimport { VirusToast } from './VirusToast.tsx'\nimport { ShieldToast } from './ShieldToast.tsx'\nimport { SpeedToast } from './SpeedToast.tsx'\nimport { readSpeed, type SpeedReading } from './speed-score.ts'\nimport { GamePoster, POSTER_WIDTH } from './GamePoster.tsx'\nimport type { AdControlsProps } from './AdControls.tsx'\nimport { retireAds, useRetired } from './retire.ts'\nimport { isSolo, useAdSettings } from './settings.ts'\nimport { usePersisted, type Anchor } from './persist.ts'\nimport { repoFromHref } from './star-check.ts'\nimport { FALLBACK_SAFE_AREA, layout, looksLikeSidebar, pickComposer, resolvePlacement, type SafeArea, type Viewport } from './placement.ts'\nimport { pruneCooling, targetCount, weightedPick, type SpawnConfig } from './schedule.ts'\nimport type { AdCreative, AdLocale, PlacedAd } from './types.ts'\n\n/** How often the layer re-checks its population target, in ms. */\nconst TICK_MS = 2000\n\n/** Gap between attempts to read the navigation timing, in ms. */\nconst SPEED_RETRY_MS = 250\n\n/** How many attempts before giving up on a browser that reports no timing. */\nconst SPEED_ATTEMPTS = 20\n\n/** Props for the ad layer. */\nexport interface AdLayerProps {\n  /** Language used by the host UI and creative pool. */\n  readonly locale?: AdLocale\n  /** The banner pool to draw from. */\n  readonly creatives: readonly AdCreative[]\n  /** The corner pop-up pool, rotated in order. */\n  readonly popups: readonly AdCreative[]\n  /** The bottom-left poster pool, rotated in order. */\n  readonly posters: readonly AdCreative[]\n  /** Growth curve. */\n  readonly spawn: SpawnConfig\n  /** Side of the real close hitbox, in CSS pixels. */\n  readonly hitboxPx: number\n  /** Delay before the corner pop-up first appears, in ms; zero disables it. */\n  readonly popupFirstDelayMs: number\n  /** Delay before the bottom-left poster first appears, in ms; zero disables it. */\n  readonly posterFirstDelayMs: number\n  /** Delay between automatic bottom-left poster changes, in ms; zero disables rotation. */\n  readonly posterRotateMs: number\n  /**\n   * Delay before a closed pop-up or poster comes back, in ms. Neither retracts\n   * on its own, so this is the only thing that paces them after the first one.\n   */\n  readonly respawnMs: number\n  /** Whether a pop-up or poster chimes on arrival. */\n  readonly chime: boolean\n  /**\n   * Delay after the benchmark window leaves before the fake security alert\n   * arrives, in ms; zero disables the alert.\n   */\n  readonly scareDelayMs: number\n  /**\n   * Where the alert's \"立即修复\" sends the user. When it points at a GitHub\n   * repository, the alert also offers star verification against it\n   * ({@link repoFromHref}); anywhere else just hides the verify row.\n   */\n  readonly scareHref: string\n  /**\n   * Delay before the benchmark result appears, in ms; zero disables it.\n   * Shorter than every other opening delay on purpose — it opens the corner's\n   * programme, and a benchmark that turned up third would have missed its\n   * moment.\n   */\n  readonly speedFirstDelayMs: number\n}\n\n/** How deep to descend from `<body>` when looking for the sidebar. */\nconst SIDEBAR_SCAN_DEPTH = 5\n\n/**\n * How deep to descend when looking for the header.\n *\n * Deeper than the sidebar scan because it has to be: the shell renders its\n * `<header>` eight levels below `<body>`, so the sidebar's depth of 5 never\n * reached it and every header measurement silently returned zero. That put\n * `safe.top` back on its 56px fallback and let both gutters start above the\n * view tabs, covering them.\n */\nconst HEADER_SCAN_DEPTH = 12\n\n/**\n * Slack added either side of the composer to derive the conversation column.\n * The transcript's own bubbles sit slightly wider than the composer card, so\n * the column has to be a touch wider than what is measured.\n */\nconst COLUMN_PAD = 12\n\n/**\n * Find the right edge of the session sidebar, geometrically.\n *\n * The sidebar is navigation, not content: burying the session list makes the\n * app unusable rather than annoying, so the layer stops at its right edge.\n * {@link looksLikeSidebar} owns what counts as one; this walk only bounds the\n * search, so a deep render tree cannot turn it into a full-document scan on\n * every tick.\n *\n * @param viewportHeight - current viewport height, in CSS pixels.\n * @returns the sidebar's right edge, or 0 when it is collapsed or absent.\n */\nfunction measureSidebar(viewportHeight: number): number {\n  let right = 0\n  const visit = (node: Element, depth: number) => {\n    if (depth > SIDEBAR_SCAN_DEPTH) return\n    const rect = node.getBoundingClientRect()\n    if (looksLikeSidebar(rect, viewportHeight)) right = Math.max(right, rect.right)\n    for (const child of node.children) visit(child, depth + 1)\n  }\n  for (const child of document.body.children) visit(child, 1)\n  return right\n}\n\n/** Deepest a header candidate may sit below the top edge, in CSS pixels. */\nconst HEADER_BAND = 140\n\n/**\n * Find the bottom of the session header — title bar plus view tabs.\n *\n * Same geometric approach as {@link measureSidebar}, for the same reason: the\n * shell has no semantic landmark and its class names are per-build hashes.\n * Candidates are wide, shallow, and anchored near the top; the deepest one\n * wins, so the tab strip under the title is included rather than clipped.\n *\n * @param viewport - current viewport size.\n * @param columnLeft - left edge of the conversation column; header candidates\n * must start at or before it, which excludes anything inside the transcript.\n * @returns the header's bottom edge, or 0 when nothing matches.\n */\nfunction measureHeader(viewport: Viewport, columnLeft: number): number {\n  let bottom = 0\n  const consider = (rect: DOMRect) => {\n    const wide = rect.width > viewport.width * 0.3\n    const shallow = rect.height > 0 && rect.height < 90 && rect.bottom < HEADER_BAND\n    if (wide && shallow && rect.left <= columnLeft) bottom = Math.max(bottom, rect.bottom)\n  }\n  // Semantics first. The shell's class names are per-build hashes, but it does\n  // render a real `<header>` and a real `role=\"tablist\"`, and the tab strip is\n  // exactly the thing a banner must not cover — it is the only control up\n  // there. Geometry alone missed both, and missing them is not a near-miss:\n  // it silently yields zero, which reads as \"no header\" rather than as a\n  // failed measurement.\n  for (const node of document.querySelectorAll('header, [role=\"tablist\"]')) consider(node.getBoundingClientRect())\n  const visit = (node: Element, depth: number) => {\n    if (depth > HEADER_SCAN_DEPTH) return\n    consider(node.getBoundingClientRect())\n    for (const child of node.children) visit(child, depth + 1)\n  }\n  for (const child of document.body.children) visit(child, 1)\n  return bottom\n}\n\n/**\n * Track whether a host modal is open.\n *\n * `[role=\"dialog\"][aria-modal=\"true\"]` is the one semantic landmark the shell\n * offers — its class names are per-build hashes — and it is the right signal\n * anyway: a modal is a claim on the user's whole attention, and an ad layer\n * that keeps painting over one has stopped being a joke about ads and started\n * being a broken window manager.\n *\n * Watched rather than polled, so the layer clears the moment the dialog opens\n * instead of on the next two-second tick.\n *\n * @returns true while a modal dialog is on screen.\n */\nfunction useModalOpen(): boolean {\n  const [open, setOpen] = useState(false)\n  useEffect(() => {\n    const check = () => setOpen(document.querySelector('[role=\"dialog\"][aria-modal=\"true\"]') !== null)\n    check()\n    const observer = new MutationObserver(check)\n    observer.observe(document.body, { childList: true, subtree: true, attributeFilter: ['role', 'aria-modal'] })\n    return () => observer.disconnect()\n  }, [])\n  return open\n}\n\n/**\n * Track the viewport size.\n * @returns the current viewport dimensions, updated on resize.\n */\nfunction useViewport(): Viewport {\n  const [viewport, setViewport] = useState<Viewport>(() => ({ width: innerWidth, height: innerHeight }))\n  useEffect(() => {\n    const onResize = () => setViewport({ width: innerWidth, height: innerHeight })\n    addEventListener('resize', onResize)\n    return () => removeEventListener('resize', onResize)\n  }, [])\n  return viewport\n}\n\n/**\n * Measure the regions banners must not cover.\n *\n * The composer is found by its input element rather than by a class name, so\n * the exclusion survives shell restyling; when nothing matches, the generous\n * {@link FALLBACK_SAFE_AREA} applies. Re-measured on the same ticker as\n * spawning, which is frequent enough for a composer that grows as the user\n * types and cheap enough to ignore.\n *\n * @param viewport - current viewport, so the hook re-measures after a resize.\n * @returns the reserved bands.\n */\nfunction useSafeArea(viewport: Viewport): SafeArea {\n  const [safe, setSafe] = useState<SafeArea>(FALLBACK_SAFE_AREA)\n  useEffect(() => {\n    const measure = () => {\n      const left = measureSidebar(viewport.height)\n      // The composer is both the bottom exclusion and the width reference for\n      // the conversation column: it is centred on the column and always\n      // present, which no transcript element is.\n      //\n      // Picking it needs care. The shell has other text inputs — the sidebar's\n      // session search above all — and taking the topmost match found that one\n      // instead, which collapsed the column onto the sidebar and let the\n      // gutters draw straight over the transcript. The composer is the input\n      // sitting lowest on screen, and it is never inside the sidebar.\n      const inputs = document.querySelectorAll('textarea, [contenteditable=\"true\"]')\n      const composer = pickComposer([...inputs].map((node) => node.getBoundingClientRect()), left)\n      const bottom = composer === undefined\n        ? FALLBACK_SAFE_AREA.bottom\n        : Math.max(FALLBACK_SAFE_AREA.top, viewport.height - composer.top + 12)\n      // A column narrower than the composer would let banners overlap the\n      // transcript, so pad the measured card outward a little.\n      const columnLeft = composer === undefined ? 0 : Math.max(left, composer.left - COLUMN_PAD)\n      const columnRight = composer === undefined ? 0 : Math.min(viewport.width, composer.right + COLUMN_PAD)\n      const header = measureHeader(viewport, columnLeft === 0 ? viewport.width / 2 : columnLeft)\n      const top = Math.max(FALLBACK_SAFE_AREA.top, header + 8)\n      setSafe({ ...FALLBACK_SAFE_AREA, top, bottom, left, columnLeft, columnRight })\n    }\n    measure()\n    const timer = setInterval(measure, TICK_MS)\n    return () => clearInterval(timer)\n  }, [viewport.height, viewport.width])\n  return safe\n}\n\n/**\n * Draw the next creative for a gutter.\n *\n * The population (14) exceeds the pool, so repeats are unavoidable; what the\n * layer owes the user is that every banner in the set gets shown before any of\n * them appears a third time. Drawing from the *least-used* tier does that,\n * where excluding everything already on screen would collapse to uniform\n * randomness once the pool ran out — which is how four copies of one banner\n * ended up on screen while another creative never appeared at all.\n *\n * @param creatives - the full pool.\n * @param weights - per-creative draw weights, index-aligned with `creatives`.\n * @param placed - banners already on screen.\n * @returns the chosen creative, or undefined when the pool is empty.\n */\nfunction pickCreative(\n  creatives: readonly AdCreative[],\n  weights: readonly number[],\n  placed: readonly PlacedAd[],\n  locale: AdLocale,\n): AdCreative | undefined {\n  const candidates = locale === 'en' ? englishGutterCandidates(creatives, placed) : creatives\n  const used = new Map<string, number>()\n  for (const ad of placed) used.set(ad.creative.id, (used.get(ad.creative.id) ?? 0) + 1)\n  let fewest = Infinity\n  for (const c of candidates) fewest = Math.min(fewest, used.get(c.id) ?? 0)\n  const pool = candidates.filter((c) => (used.get(c.id) ?? 0) === fewest)\n  const w = pool.map((c) => weights[creatives.indexOf(c)] ?? c.weight)\n  return pool[weightedPick(w, Math.random())]\n}\n\n/**\n * Keep both English skyscraper treatments above the fold, then spend the\n * remaining population on shorter banners that still fit below them.\n *\n * The selected community plugins remain random per conversation. This only\n * controls shape and tier: the generated sponsored skyscraper occupies the\n * first gutter, a built-in skyscraper occupies the other, and horizontal\n * inventory fills the remaining slots.\n *\n * @param creatives - localized built-ins plus selected community plugins.\n * @param placed - banners already spawned in this population.\n * @returns the candidates allowed for the next draw.\n */\nexport function englishGutterCandidates(\n  creatives: readonly AdCreative[],\n  placed: readonly PlacedAd[],\n): readonly AdCreative[] {\n  if (placed.length === 0) {\n    const sponsoredTall = creatives.filter((creative) => creative.shape === 'tall' && creative.sponsor !== undefined)\n    if (sponsoredTall.length > 0) return sponsoredTall\n  }\n  if (placed.length === 1) {\n    const builtinTall = creatives.filter((creative) => creative.shape === 'tall' && creative.sponsor === undefined)\n    if (builtinTall.length > 0) return builtinTall\n  }\n  if (placed.length >= 2) {\n    const horizontal = creatives.filter((creative) => creative.shape !== 'tall')\n    if (horizontal.length > 0) return horizontal\n  }\n  return creatives\n}\n\n\n/**\n * Mount the layer.\n * @param props - see {@link AdLayerProps}.\n * @returns a portal carrying every live banner, or null before the first spawn.\n */\nexport function AdLayer(props: AdLayerProps) {\n  const { creatives, popups, posters, spawn, hitboxPx, chime } = props\n  const locale = props.locale ?? 'zh'\n  const {\n    popupFirstDelayMs, posterFirstDelayMs, posterRotateMs, respawnMs,\n    scareDelayMs, scareHref, speedFirstDelayMs,\n  } = props\n  const viewport = useViewport()\n  const safe = useSafeArea(viewport)\n  const modalOpen = useModalOpen()\n  const [ads, setAds] = useState<readonly PlacedAd[]>([])\n  // Reopen timestamps for slots the user has closed. One entry suppresses one\n  // banner until it expires; see schedule.ts for why the target is expressed\n  // this way rather than as a running dismissal count.\n  const [cooling, setCooling] = useState<readonly number[]>([])\n  const [takeover, setTakeover] = useState<PlacedAd | undefined>(undefined)\n  const [popup, setPopup] = useState<PlacedAd | undefined>(undefined)\n  // The fake security alert holds the bottom-right corner before the pop-up\n  // does. Which face it wears — threat or protection report — is latched when\n  // it fires, not read live: a verification succeeding mid-display must let\n  // the 修复成功 panel finish its moment instead of yanking it away.\n  const [scare, setScare] = useState<{ seed: number; shield: boolean } | undefined>(undefined)\n  // The benchmark result, once measured. Same corner, strictly after the alert.\n  const [speed, setSpeed] = useState<{ reading: SpeedReading; seed: number } | undefined>(undefined)\n  const [poster, setPoster] = useState<PlacedAd | undefined>(undefined)\n  // \"关闭所有广告\" lives in its own module because the button that presses it\n  // sits in the host's settings dialog, a different React tree. See retire.ts\n  // for why it is page-load state rather than a stored setting.\n  const retired = useRetired()\n  // Which placements are switched on, and whether they chime. Stored, shared\n  // with the host's own settings page, and the reason the layer can be pared\n  // down to \"just the whale and the benchmark\" and stay that way.\n  const [settings, setSettings] = useAdSettings()\n  const muted = settings.muted\n  const solo = isSolo(settings)\n  const [collapsed, setCollapsed] = usePersisted('poster-collapsed', false)\n  const [anchor, setAnchor] = usePersisted<Anchor | null>('poster-anchor', null)\n  // The security alert's star status. Persistent, unlike dismissals: the user\n  // did the one thing the alert asked for, and a cure that wears off on\n  // refresh would make the verify row a lie. Verification does not stop the\n  // corner slot — it flips it to the protection report, which arrives on the\n  // same schedule and gloats instead of threatening. The id is kept too, so\n  // the next attempt (this browser, any day) starts prefilled.\n  const [starVerified, setStarVerified] = usePersisted('star-verified', false)\n  const [githubId, setGithubId] = usePersisted('github-id', '')\n  // Mirrored into a ref so the scare timer can read the value current at fire\n  // time without re-arming whenever verification flips it.\n  const starVerifiedRef = useRef(starVerified)\n  useEffect(() => { starVerifiedRef.current = starVerified }, [starVerified])\n  const mountedAt = useRef(Date.now())\n  const spawnedTotal = useRef(0)\n  const placements = useRef(0)\n  const popupRound = useRef(0)\n  const scareRound = useRef(0)\n  const speedRound = useRef(0)\